\[\label{eq:P} \tag{\text{P}}%
			\minimize_{x\in\overline{C}}
			\varphi(x)
			\coloneqq
			f(x) + g(x),
		\]

		where \(\overline{C}\) denotes the closure of \(C \coloneqq \interior\dom\kernel\) for a proper \(1\)-coercive function \(\kernel:\R^n\to\Rinf\) of Legendre type, \(f:\R^n\to\Rinf\), \(g:\R^n\to\Rinf\)  are proper closed convex, while \(f\) is only assumed to be \emph{locally} smooth relative to the \emph{distance-generating function} (dgf).
		By local smoothness relative to \(\kernel\) we refer to the existence, for any compact and convex set \(\K\subset\interior\dom\kernel\), of a constant \(L_{f,\K}^{\kernel}\geq0\) such that \(L_{f,\K}^{\kernel}\kernel-f\) is convex over \(\K\); see \cref{ass:basic}.


\begin{equation}\label{eq:BPG}
			x^{k+1}
		=
			\argmin_{w\in\R^n}\left\{
				f(x^k)+\innprod{\nabla f(x^k)}{w-x^k}+g(w)+\tfrac{1}{\gamma_{k+1}}\D_{\kernel}(w,x^k)
			\right\},
		\end{equation}

\begin{equation}\label{eq:D}
			\D_{\kernel}(x, y)
		\coloneqq
			\begin{cases}
				\kernel(x) - \kernel(y) - \innprod{\nabla\kernel(y)}{x - y} & \text{if }(x,y)\in\dom\kernel\times\interior\dom\kernel
			\\
				\infty & \text{otherwise}
			\end{cases}
		\end{equation}

			The set of natural numbers is \(\N\coloneqq\{0,1,2,\dots\}\), while \(\R\), \(\R_{++}\coloneqq(0,\infty)\), and \(\Rinf\coloneqq\R\cup\{\pm\infty\}\) denote the set of real, strictly positive, and extended-real numbers, respectively.
			For \(t\in\R\), we define \([t]_+\coloneqq\max\{t,0\}\).


			The \emph{domain} and \emph{epigraph} of an extended-real-valued function \(h:\R^n\to\Rinf\) are the sets
			\(
				\dom h
			\coloneqq
				\{x\in\R^n \mid h(x)<\infty\}
			\)
			and
			\(
				\epi h
			\coloneqq
				\{(x, c)\in\R^n\times\R \mid h(x)\leq c\}
			\).
			Function \(h\) is said to be: \emph{proper} if \(h>-\infty\) and \(\dom h\neq\emptyset\); \emph{lower semicontinuous (lsc)} if \(\epi h\) is a closed subset of \(\R^{n+1}\); \emph{1-coercive} if
			\(
				\lim_{\norm{x}\to\infty}\frac{h(x)}{\norm{x}}=\infty
			\).

			The \emph{conjugate} of a proper, lsc, convex function \(h:\R^n\to\Rinf\) is the proper, lsc, convex function \(h^*:\R^n\to\Rinf\) defined by
			\(
				h^*(\xi)
			\coloneqq
				\sup_{x\in\R^n}\{\innprod{\xi}{x}-h(x)\}
			\).
			The \emph{(convex) subdifferential} of \(h\) at \(x\in\dom h\) is the set
			\[
				\partial h(x)
			\coloneqq
				\{u\in\R^n \mid h(x')\geq h(x)+\innprod{u}{x'-x} ~ \forall x'\in\R^n\},
			\]
			while \(\partial h(x)=\emptyset\) for \(x\notin\dom h\).
			\(h\) is differentiable at \(x\) iff \(\partial h(x)\) is a singleton, and in this case one has that \(\partial f(x)=\{\nabla h(x)\}\).


				We say that a proper, lsc, convex function \(\kernel:\R^n\to\Rinf\) is \emph{of Legendre type} (or simply \emph{Legendre}) if it is
				(i) \emph{essentially smooth}, namely differentiable on \(\interior\dom\kernel\neq\emptyset\) and such that \(\norm{\nabla\kernel(x^k)}\to\infty\) whenever \(\interior\dom\kernel\ni x^k\to x\in\dom\kernel\setminus\interior\dom\kernel\), and
				(ii) \emph{essentially strictly convex}, namely strictly convex on every convex subset of \(\dom\partial\kernel\).


\begin{equation}\label{eq:DD}
					\DD_{\kernel}(x,y)
				\coloneqq
					\D_{\kernel}(x,y)+\D_{\kernel}(y,x)
				=
					\begin{cases}
						\innprod{\nabla\kernel(x)-\nabla\kernel(y)}{x - y} & \hspace*{-7pt}\text{if } x,y\in\interior\dom\kernel
					\\
						\infty & \hspace*{-7pt}\text{otherwise.}
					\end{cases}
				\end{equation}

\begin{assumption}\label{ass:basic}%
			The following hold in \eqref{eq:P}:
			\begin{enumerate}
			\item \label{ass:h}%
				\(C=\interior\dom\kernel\) for a proper, convex, 1-coercive function \(\kernel\) of Legendre type, which is twice continuously differentiable with \(\nabla^2\kernel \succ 0\) on \(C\).
			\item \label{ass:f}%
				\(f:\R^n\to\Rinf\) is proper, convex, lsc, and \emph{locally smooth relative to \(\kernel\)}:
				that is, \(\dom\kernel\subseteq\dom f\), and for every convex and compact set \(\K\subset C\) there exists \(L_{f,\K}^{\kernel}>0\) such that \(L_{f,\K}^{\kernel}\kernel-f\) is convex on \(\K\).
			\item \label{ass:g}%
				\(g:\R^n\to\Rinf\) is proper, lsc, and convex with \(\dom g\cap C\neq\emptyset\).
			\item \label{ass:argmin}%
				A solution exists: \(\argmin_{\overline C}\varphi\neq\emptyset\).
			\end{enumerate}
		\end{assumption}

		The local relative smoothness in \cref{ass:f} is tantamount to saying that \(f\) is differentiable on \(C\),\footnote{%
			See \cite[Prop. 3.7]{wang2024mirror} or \cite[Prop. 2.5]{ahookhosh2021bregman}.
		}
		and that


\begin{equation}\label{eq:Df<D}
			\D_f(x, y)\leq L_{f,\K}^{\kernel}\D_{\kernel}(x, y)
		\quad
			\forall x,y\in\K,
		\end{equation}

\begin{assumption}[Bregman with zone \(C\) {\cite[Def. 2.1]{solodov2000inexact}}]\label{ass:zone}%
			The dgf \(\kernel\) satisfies the following:
			\begin{enumerate}
			\item \label{ass:Dhto0}%
				\(\D_{\kernel}(x, x^k) \to 0\) whenever \(C \ni x^k \to x\) (in particular, \(\dom\kernel\) is closed).
			\item \label{ass:xkbounded}%
				\(\D_{\kernel}(x,{}\cdot{})\) is level bounded for any \(x\in\overline{C}\setminus C\).
			\end{enumerate}
		\end{assumption}

\begin{equation}\label{eq:Hk}
				H_k\coloneqq\nabla\kernel-\gamma_k\nabla f,
			\end{equation}

\begin{equation}\label{eq:lk}
						\ell_k
					\coloneqq
						\frac{\DD_f(x^k,x^{k-1})}{\DD_{\kernel}(x^k,x^{k-1})}
					\end{equation}

\begin{equation}\label{eq:Lamk}
						\Lambda_{k,\delta}
					\coloneqq
						\frac{
							2\D_{\kernel^*}\bigl(\nabla\kernel(x^k)+\delta\bigl[H_k(x^k)-H_k(x^{k-1})\bigr],\nabla\kernel(x^k)\bigr)
						}{
							\delta^2\DD_{\kernel}(x^k,x^{k-1})
						}
					\end{equation}

					depending on some parameter \(\delta>0\) (specified later).


\begin{equation}\label{eq:ak}
						\alpha_k
					\coloneqq
						\frac{\D_{\kernel}(x^k,x^{k-1})}{\D_{\kernel}(x^{k-1},x^k)}
					\in
						(0,\infty)
					\end{equation}

\begin{equation}
				\DD_{\kernel}(x^k,x^{k-1})
			=
				\tfrac{1+\alpha_k}{\alpha_k}\D_{\kernel}(x^k,x^{k-1}).
			\end{equation}

\begin{equation}\label{eq:alpha}
				\alpha(\kernel)
			\coloneqq
				\inf_{\substack{x,y\in\interior\dom\kernel\\x\neq y}}\frac{\D_{\kernel}(x,y)}{\D_{\kernel}(y,x)}.
			\end{equation}

			Based on these three quantities, choose a stepsize \(\gamma_{k+1}\) and proceed with a Bregman proximal gradient update \eqref{eq:BPG}.
			We propose the following two options, where we let
			\[
				\rho_{k+1}
			\coloneqq
				\tfrac{\gamma_{k+1}}{\gamma_k}
			\]
			denote the ratio of consecutive stepsizes (so that \(\gamma_{k+1}=\rho_{k+1}\gamma_k\)):

			\medskip
			\par\noindent\phantomsection \label{alg:BY}%
				\parbox[t]{0.15\linewidth}{\bf\BY}%
				\hfill
				\fbox{\parbox[t]{0.82\linewidth}{%
					set \(\hat\rho_{k+1}=\sqrt{1+\rho_k}\) and \(\delta=2\hat\rho_{k+1}\), and update
					\begin{equation}\label{eq:BY:rhok*}
						\rho_{k+1}
					=
						\min\left\{
							\hat\rho_{k+1}
						,
							\frac{\alpha_k}{1+\alpha_k}
							\frac{
								1
							}{
								2\hat\rho_{k+1}
								\left[
									\Lambda_{k,\delta}
									-
									(1-\gamma_k\ell_k)
								\right]_+
							}
						\right\}
					\end{equation}
				}}%

			\medskip
			\noindent
			and, in case \(\kernel\) enjoys a symmetry coefficient \(\alpha=\alpha(\kernel)>0\),
			\medskip

			\par\noindent\phantomsection \label{alg:FNEa}%
				\parbox[t]{0.15\linewidth}{%
					{\bf\FNEa}

					\footnotesize
					(if \(\alpha(\kernel)>0\))%
				}
				\hfill
				\fbox{\parbox[t]{0.82\linewidth}{%
					set \(\hat\rho_{k+1}=\sqrt{\frac{1+\alpha}{2}+\rho_k}\) and \(\delta=\frac{2}{1+\alpha}\hat\rho_{k+1}\), and update
					\begin{equation}\label{eq:FNEa:rhok*}
						\rho_{k+1}
					=
						\min\left\{
							\hat\rho_{k+1}
						,
							\frac{\alpha}{
								2\hat\rho_{k+1}
								\left[
									\Lambda_{k,\delta}
									-
									(1-\gamma_k\ell_k)
								\right]_+
							}
						\right\}.
					\end{equation}
				}}%


				We use the convention that \(\frac{1}{0}=\infty\), and remind that \([t]_+=\max\{0,t\}\).
				In particular, whenever \(\Lambda_{k,\delta}\leq1-\gamma_k\ell_k\) all updates reduce to \(\rho_{k+1}=\hat\rho_{k+1}\).
				It is implied that a starting point \(x^0\in C\) should be provided, as well as two stepsizes \(\gamma_0,\gamma_1>0\) for the first two iterations.


		To ease the subsequent discussion, we introduce some convenient notational shorthands and remind some of those already encountered.
		Relative to the iterates generated by \eqref{eq:BPG}, for any \(k\in\N\) and \(x\in\dom\varphi\) we denote
		\begin{align}
		\label{eq:Pk}
			P_k(x)
		\coloneqq{} &
			\varphi(x^k)-\varphi(x)
		\shortintertext{and}
		\label{eq:Bk}
			B_{k+1}
		\coloneqq{} &
			\rho_{k+1}
			\innprod{x^{k+1}-x^k}{H_k(x^k)-H_k(x^{k-1})},
		\end{align}
		where \(\rho_{k+1}=\tfrac{\gamma_{k+1}}{\gamma_k}\) and
		\begin{equation}\label{eq:H:def}
			H_k\coloneqq\nabla\kernel-\gamma_k\nabla f
		\end{equation}
		is the ``forward'' operator.
		Due to convexity of \(g\), the BPG updates in \eqref{eq:BPG} are characterized by the subgradient inclusion
		\begin{subequations}
			\begin{align}
			\label{eq:subgrad}
				\tilde{\nabla}g(x^{k+1})
			\coloneqq{} &
				\tfrac{\nabla\kernel(x^k)-\nabla\kernel(x^{k+1})}{\gamma_{k+1}}
				-
				\nabla f(x^k)
			\in
				\partial g(x^{k+1}).
			\intertext{%
				Throughout, we use the notation \(\tilde{\nabla}g(x^{k+1})\) to indicate this particular element of the subgradient of \(g\) along the iterates.
				Similarly, we use
			}
			\nonumber
				\tilde{\nabla}\varphi(x^{k+1})
			\coloneqq{} &
				\tilde{\nabla} g(x^{k+1})
				+
				\nabla f(x^{k+1})
			\\
			\label{eq:subgradvarphi}
			={} &
				\tfrac{H_{k+1}(x^k)-H_{k+1}(x^{k+1})}{\gamma_{k+1}}
			\in
				\partial\varphi(x^{k+1}).
			\end{align}
		\end{subequations}
		In light of these, we adopt the notation
		\begin{gather*}
			\tD_g(w,x^k)
		\coloneqq
			g(w)-g(x^k)-\innprod{\tilde{\nabla}g(x^k)}{w-x^k},
		\shortintertext{and similarly}
			\tD_{\varphi}(w,x^k)
		\coloneqq
			{\varphi}(w)-{\varphi}(x^k)-\innprod{\tilde{\nabla}{\varphi}(x^k)}{w-x^k},
		\end{gather*}
		which are both positive quantities for any \(k\in\N\) and \(w\in\R^n\).

