\begin{theorem}[summary of main results]\label{thm:main}%
					Suppose that \cref{ass:basic} holds, and consider the iterates generated by \refBY{}.
					Then, one always has that
					\begin{equation}\label{eq:main:inf}
						\smash{
							\inf_{k\in\N}\varphi(x^k)=\inf_{\overline{C}}\varphi.
						}
					\end{equation}
					Moreover,
					\begin{enumerate}
					\item \label{thm:main:C}%
						If \(C\cap\argmin_{\overline{C}}\varphi\neq \emptyset\) (equivalently, if \(C\cap\argmin\varphi\neq\emptyset\)), then there exists \(x^\star\in C\cap \argmin\varphi\) such that \(x^k\to x^\star\).
					\item \label{thm:main:zone}%
						If \cref{ass:zone} holds, then \((x^k)_{k\in\N}\) is bounded and admits a unique optimal limit point.
					\end{enumerate}
					When \(\kernel\) has symmetry coefficient \(\alpha>0\), the same is true for \refFNEa.
				\end{theorem}

