\begin{fact}[three-point identity {\cite[Lem. 3.1]{chen1993convergence}}]\label{thm:3p}%
					Let \(\kernel:\R^n\to\Rinf\) be a proper lsc convex function differentiable on \(\interior\dom\kernel\).
					For any \(x\in\dom\kernel\), and \(y,z\in\interior\dom\kernel\) the following holds:
					\[
						\D_{\kernel}(x,z)
					=
						\D_{\kernel}(x,y)
						+
						\D_{\kernel}(y,z)
						+
						\innprod{x-y}{\nabla\kernel(y)-\nabla\kernel(z)}.
					\]
				\end{fact}

\begin{fact}\label{fact:D}%
					Let \(\kernel:\R^n\to\Rinf\) be of Legendre type, and let \(C\coloneqq\interior\dom\kernel\).
					\begin{enumerate}
					\item \label{fact:D:coercive}%
							{\upshape \cite[Prop. 2.16]{bauschke1997legendre}, \cite[Thm. 3.7(vi)]{bauschke1997legendre}}
							If \(\kernel\) is 1-coercive, then \(\dom\kernel^*=\R^n\) and \(\D_{\kernel}(x,{}\cdot{})\) is coercive for any \(x\in C\).

					\item \label{fact:D:boundary}%
						{\upshape \cite[Thm. 3.8(i)]{bauschke1997legendre}}
						If a sequence \((x^k)_{k\in\N}\) converges to a boundary point of \(C\), then \(\D_{\kernel}(x,x^k)\to\infty\) for any \(x\in C\).

					\item \label{fact:D:solodov}%
						{\upshape \cite[Thm. 2.4]{solodov2000inexact}}
						Suppose that \(\dom\kernel\) is closed and that \(\D_{\kernel}(x^k,y^k)\to0\).
						If either \((x^k)_{k\in\N}\) or \((y^k)_{k\in\N}\) converges, then the other sequence too converges to the same limit.

					\item \label{fact:D:Dphi*}%
						{\upshape \cite[Thm. 26.5]{rockafellar1970convex}}
						The conjugate \(\kernel^*\) is continuously differentiable and strictly convex on \(\interior\dom\kernel^*\), with \(\nabla\kernel^* = \nabla\kernel^{-1}:\interior\dom\kernel^*\to\interior\dom\kernel\).

					\item \label{fact:D:DtoD*}%
						{\upshape \cite[Thm. 3.7(v)]{bauschke1997legendre}}
						\(\D_{\kernel}(x,y) = \D_{\kernel^*}(\nabla \kernel(y), \nabla \kernel(x))\) for any \(x,y\in C\).
					\end{enumerate}
				\end{fact}

\begin{lemma}[main identity]\label{thm:eq}%
			Suppose that \cref{ass:basic} holds, and starting from \(x^0\in C\) consider Bregman proximal gradient iterations \eqref{eq:BPG} with stepsizes \(\gamma_k>0\).
			Then, for any \(x\in\dom\varphi\cap\dom\kernel\), \(\vartheta_{k+1}\geq0\), \(k\in\N\), it holds that
			\begin{align*}
			&
				\D_{\kernel}(x,x^{k+1})
				+
				\gamma_{k+1}(1+\vartheta_{k+1})P_k(x)
				+
				\D_{\kernel}(x^{k+1},x^k)
			\\
			={} &
				\D_{\kernel}(x,x^k)
				+
				\gamma_{k+1}\vartheta_{k+1} P_{k-1}(x)
				-
				\rho_{k+1}\vartheta_{k+1}(1-\gamma_k\ell_k)
				\DD_{\kernel}(x^k,x^{k-1})
				+
				B_{k+1}
			\\
			&
				-
				\gamma_{k+1}
				\Bigl\{
					\D_f(x,x^k)
					+
					\tD_g(x^{k+1},x^k)
					+
					\tD_g(x,x^{k+1})
					+
					\vartheta_{k+1}\tD_\varphi(x^{k-1},x^k)
				\Bigr\},
			\end{align*}
			where \(P_k(x)\), \(B_{k+1}\), and \(\ell_k\) are as in \eqref{eq:Pk}, \eqref{eq:Bk}, and \eqref{eq:lk}.
			In particular, denoting
			\[
				\widehat{\U}_k(x)
			\coloneqq
				\D_{\kernel}(x,x^k)
				+
				\gamma_k(1+\vartheta_k)P_{k-1}(x)
				+
				\D_{\kernel}(x^k,x^{k-1}),
			\]
			one has that
			\begin{align}
			\nonumber
				\widehat{\U}_{k+1}(x)
			\leq{} &
				\widehat{\U}_k(x)
				-
				\gamma_k(1+\vartheta_k-\rho_{k+1}\vartheta_{k+1})P_{k-1}(x)
				+
				B_{k+1}
			\\
			&
				-
				\left[
					\tfrac{\alpha_k}{1+\alpha_k}
					+
					\rho_{k+1}\vartheta_{k+1}(1-\gamma_k\ell_k)
				\right]
				\DD_{\kernel}(x^k,x^{k-1}).
			\label{eq:ineq0}
			\end{align}
		\end{lemma}

\begin{proof}
			See \cref{proof:thm:eq}.
		\end{proof}

\begin{lemma}[Young's inequality in the Bregman sense]\label{thm:BY}%
				Let \(\kernel:\R^n\to\Rinf\) be Legendre (not necessarily 1-coercive).
				Then, for any \(x\in\dom\kernel\), \(y\in\interior\dom\kernel\), \(v\in\R^n\), and \(\delta>0\) one has
				\begin{equation}\label{eq:BY}
					\innprod{x-y}{v}
				\leq
					\tfrac{1}{\delta}
					\D_{\kernel}(x,y)
					+
					\tfrac{1}{\delta}
					\D_{\kernel^*}\bigl(\nabla\kernel(y)+\delta v,\nabla\kernel(y)\bigr).
				\end{equation}
			\end{lemma}

\begin{proof}
				Without loss of generality we may assume that \(\nabla\kernel(y)+\delta v\in\dom\kernel^*\), for otherwise the right-hand side of \eqref{eq:BY} is infinite and the inequality trivializes.
				Since \(\nabla\kernel(y)\in\interior\dom\kernel^*\) by \cref{fact:D:Dphi*}, for any \(t\in(0,1)\) one has that
				\(
					\nabla\kernel(y)+t\delta v\in\interior\dom\kernel^*
				\)
				by \cite[Prop. 3.44]{bauschke2017convex}.
				We have
				\begin{align*}
					\innprod{x-y}{v}
				={} &
					\tfrac{1}{t\delta}
					\innprod{x-y}{t\delta v}
				\\
				={} &
					\tfrac{1}{t\delta}
					\innprod{x-y}{\nabla\kernel(\nabla\kernel^*\bigl(\nabla\kernel(y)+t\delta v)\bigr)-\nabla\kernel(y)}
				\\
				={} &
					\tfrac{1}{t\delta}
					\D_{\kernel}(x,y)
					+
					\tfrac{1}{t\delta}
					\D_{\kernel}\bigl(y,\nabla\kernel^*\bigl(\nabla\kernel(y)+t\delta v\bigr)\bigr)
				\\
				&
					-
					\tfrac{1}{t\delta}
					\D_{\kernel}\bigl(x,\nabla\kernel^*\bigl(\nabla\kernel(y)+t\delta v\bigr)\bigr)
				\\
				\leq{} &
					\tfrac{1}{t\delta}
					\D_{\kernel}(x,y)
					+
					\tfrac{1}{t\delta}
					\D_{\kernel^*}\bigl(\nabla\kernel(y)+t\delta v,\nabla\kernel(y)\bigr).
			\end{align*}
				The second equality follows from Legendreness of \(\kernel\) via \cref{fact:D:Dphi*}, and the third one is the three point identity of \cref{thm:3p}.
				The inequality follows from \cref{fact:D:DtoD*} and the fact that \(\D_\kernel\geq0\).
				By taking the limit as \(t\to1^-\) and appealing to \cite[Thm. 7.5]{rockafellar1970convex}, the claimed inequality \eqref{eq:BY} is obtained.
			\end{proof}

				A direct application of Young's inequality of \cref{thm:BY} allows us to bound the inner product \(B_{k+1}\) as
				\begin{align}
				\nonumber
					B_{k+1}
				\leq{} &
					\tfrac{\rho_{k+1}}{\delta_{k+1}}\D_{\kernel}(x^{k+1},x^k)
				\\
				\nonumber
				&
					+
					\tfrac{\rho_{k+1}}{\delta_{k+1}}\D_{\kernel^*}\bigl(\nabla\kernel(x^k)+\delta_{k+1}\bigl[H_k(x^k)-H_k(x^{k-1})\bigr],\nabla\kernel(x^k)\bigl)
				\shortintertext{%
					for any \(\delta_{k+1}>0\), which in terms of the Lipschitz-like estimate \(\Lambda_{k,\delta}\) as in \eqref{eq:Lamk} reads
				}
				={} &
					\tfrac{\rho_{k+1}}{\delta_{k+1}}\D_{\kernel}(x^{k+1},x^k)
					+
					\tfrac{\delta_{k+1}\rho_{k+1}}{2}
					\Lambda_{k,\delta_{k+1}}
					\DD_{\kernel}(x^k,x^{k-1}).
				\label{eq:Bk:BY}
				\end{align}
				As we will see, the employment of this inequality combined with a specific choice of \(\delta_{k+1}\) will lead to the stepsize update in the \refBY{} variant.


\begin{lemma}\label{thm:FNE}
					Let \(\kernel:\R^n\to\Rinf\) be Legendre, and \(f,g:\R^n\to\Rinf\) be proper, lsc, and convex, with \(f\) differentiable on \(C\coloneqq\interior\dom\kernel\) and \(\dom g\cap C\neq\emptyset\).
					Then, denoting \(H_k\coloneqq\nabla\kernel-\gamma_k\nabla f\), Bregman proximal gradient iterations \eqref{eq:BPG} with stepsizes \(\gamma_k>0\) and starting at some \(x^0\in C\) satisfy
					\[
						B_{k+1}
					\coloneqq
						\tfrac{\gamma_{k+1}}{\gamma_k}
						\innprod{x^{k+1}-x^k}{H_k(x^k)-H_k(x^{k-1})}
					\geq
						\DD_{\kernel}(x^{k+1},x^k)
					\quad
						\forall k\geq 1.
					\]
				\end{lemma}

\begin{proof}
					Follows by observing that
					\begin{align*}
					&
						\tfrac{\gamma_{k+1}}{\gamma_k}
						\bigl(H_k(x^k)-H_k(x^{k-1})\bigr)
					\\
					={} &
						\nabla\kernel(x^{k+1})-\nabla\kernel(x^k)
						+
						\gamma_{k+1}
						\Bigl[
							\smash{
								\overbrace{
									\tfrac{H_{k+1}(x^k)-\nabla\kernel(x^{k+1})}{\gamma_{k+1}}
								}^{\tilde{\nabla}g(x^{k+1})}
								-
								\overbrace{
									\tfrac{H_k(x^{k-1})-\nabla\kernel(x^k)}{\gamma_k}
								}^{\tilde{\nabla}g(x^k)}
							}
						\Bigr],
					\end{align*}
					hence that
					\(
						B_{k+1}
					=
						\DD_{\kernel}(x^{k+1},x^k)
						+
						\gamma_{k+1}\tD_g(x^{k+1},x^k)
					\geq
						\DD_{\kernel}(x^{k+1},x^k)
					\).
				\end{proof}

				We may thus complement \eqref{eq:Bk:BY} with a lower bound as
				\begin{align*}
					\DD_{\kernel}(x^{k+1},x^k)
				\leq{} &
					B_{k+1}
				\\
				\leq{} &
					\tfrac{\rho_{k+1}}{\delta_{k+1}}\D_{\kernel}(x^{k+1},x^k)
					+
					\tfrac{\delta_{k+1}\rho_{k+1}}{2}
					\Lambda_{k,\delta_{k+1}}
					\DD_{\kernel}(x^k,x^{k-1}).
				\end{align*}
				If \(\kernel\) has symmetry coefficient \(\alpha>0\) as in \eqref{eq:alpha}, then note that
				\[
					\DD_{\kernel}(x^{k+1},x^k)
				\geq
					(1+\alpha)\D_{\kernel}(x^{k+1},x^k).
				\]
				Combined with the previous inequality, we obtain
				\[
					\left(
						1+\alpha-\tfrac{\rho_{k+1}}{\delta_{k+1}}
					\right)
					\D_{\kernel}(x^{k+1},x^k)
				\leq
					\tfrac{\delta_{k+1}\rho_{k+1}}{2}
					\Lambda_{k,\delta_{k+1}}
					\DD_{\kernel}(x^k,x^{k-1}),
				\]
				which plugged into \eqref{eq:Bk:BY} leads to
				\begin{equation}
				\label{eq:Bk:FNEa}
					B_{k+1}
				\leq
					\tfrac{
						(1+\alpha)\delta_{k+1}^2
					}{
						(1+\alpha)\delta_{k+1}-\rho_{k+1}
					}
					\tfrac{\rho_{k+1}}{2}
					\Lambda_{k,\delta_{k+1}}
					\DD_{\kernel}(x^k,x^{k-1}),
				\end{equation}
				holding for any \(\delta_{k+1}\) such that \((1+\alpha)\delta_{k+1}-\rho_{k+1}>0\).


			By bounding the inner product term \(B_{k+1}\) with \eqref{eq:Bk:BY}, the inequality \eqref{eq:ineq0} in \cref{thm:eq} reveals that Bregman proximal gradient iterations \eqref{eq:BPG} with arbitrary stepsizes \(\gamma_k>0\) satisfy
			\begin{align}
			\nonumber
			&
				\widehat{\U}_{k+1}(x)
				-
				\tfrac{\rho_{k+1}}{\delta_{k+1}}
				\D_{\kernel}(x^{k+1},x^k)
			\\
			\nonumber
			\leq{} &
				\widehat{\U}_k(x)
				-
				\tfrac{\rho_k}{\delta_k}
				\D_{\kernel}(x^k,x^{k-1})
				-
				\gamma_k(1+\vartheta_k-\rho_{k+1}\vartheta_{k+1})P_{k-1}(x)
			\\
			&
				-
				\left[
					\bigl(1-\tfrac{\rho_k}{\delta_k}\bigr)
					-
					\rho_{k+1}(1+\alpha_k)
					\tfrac{
						\frac{\delta_{k+1}}{2}
						\Lambda_{k,\delta_{k+1}}
						-
						\vartheta_{k+1}
						(1-\gamma_k\ell_k)
					}{\alpha_k}
				\right]
				\D_{\kernel}(x^k,x^{k-1})
			\label{eq:UkBYdt:leq}
			\end{align}
			for any \(x\in\dom\varphi\cap\dom\kernel\), \(\vartheta_k\geq0\), and \(\delta_k>0\), \(k\in\N\).
			Imposing that the terms in brackets multiplying \(P_{k-1}(x)\) and \(\D_{\kernel}(x^k,x^{k-1})\) in the right-hand side of \eqref{eq:UkBYdt:leq} are negative amounts to the following two conditions:
			\begin{subequations}\label{eq:gamk:ineq12}
				\begin{gather}
				\label{eq:gamk:ineq1}
					\vartheta_{k+1}\rho_{k+1}\leq 1+\vartheta_k
				\shortintertext{and}
				\label{eq:gamk:ineq2}
					1-\tfrac{\rho_k}{\delta_k}
				\geq
					\rho_{k+1}
					\tfrac{1+\alpha_k}{\alpha_k}
					\bigl[
						\tfrac{\delta_{k+1}}{2}
						\Lambda_{k,\delta_{k+1}}
						-
						\vartheta_{k+1}(1-\gamma_k\ell_k)
					\bigr].
				\end{gather}
			\end{subequations}
			In line with the analyses of \cite{malitsky2020adaptive,latafat2024adaptive}, a convenient choice for the parameter \(\delta_{k+1}\) is \(\delta_{k+1} = 2\rho_{k+1}\).
			However, this choice is not feasible in our more general setting.
			Specifically, selecting \(\rho_{k+1}\) to satisfy \eqref{eq:gamk:ineq2} requires knowledge of the quantity \(\Lambda_{k,\delta_{k+1}}\), which generally depends on \(\delta_{k+1}\) itself (except in the special case where \(\kernel\) is quadratic).
			As a result, setting \(\delta_{k+1}=2\rho_{k+1}\) would create a circular dependency between the two parameters.
			To complicate things further, note that the left-hand side of \eqref{eq:gamk:ineq2} indicates that a constraint \(\delta_k>\rho_k\) must be in place in order to ensure the existence of a \(\rho_{k+1}>0\) satisfying the inequality.


			In order to resolve this circular dependence, we introduce a parameter \(\hat\rho_{k+1}\) that shall provide an overestimate
			\begin{equation}\label{eq:rhokhatgeq}
				\hat\rho_{k+1}\geq\rho_{k+1}
			\end{equation}
			while only being based on information available at iteration \(k\).
			Its explicit value will be revealed shortly after.
			Then, we may conveniently select \(\delta_k=2\hat\rho_k\) and \(\vartheta_k=\hat\rho_k\) so that \eqref{eq:gamk:ineq12} simplifies as
			\[
				\rho_{k+1}\hat\rho_{k+1}
			\leq
				1+\hat\rho_k
			\quad\text{and}\quad
				1-\tfrac{\rho_k}{2\hat\rho_k}
			\geq
				\rho_{k+1}
				\hat\rho_{k+1}
				\tfrac{1+\alpha_k}{\alpha_k}
				\bigl[
					\Lambda_{k,\delta_{k+1}}
					-
					(1-\gamma_k\ell_k)
				\bigr],
			\]
			that is,
			\begin{equation}\label{eq:BY:rhok*+}
				\rho_{k+1}
			\leq
				\min\left\{
					\frac{1+\hat\rho_k}{\hat\rho_{k+1}}
					,\,
					\frac{\alpha_k}{1+\alpha_k}
					\frac{
						1+ \frac{\hat\rho_k - \rho_k}{\hat\rho_k}
					}{
						2\hat\rho_{k+1}
						\bigl[
							\Lambda_{k,2\hat\rho_{k+1}}
							-
							(1-\gamma_k\ell_k)
						\bigr]_+
					}
				\right\}.
			\end{equation}
			Due to \eqref{eq:rhokhatgeq} the term \(\frac{\hat\rho_k - \rho_k}{\hat\rho_k}\) in the numerator of the second update is always nonnegative.
			Using this, we show in the next lemma that the update rule of \refBY{} always complies with the above bound.
			In fact, while it is possible to retain the term \(\frac{\hat\rho_k - \rho_k}{\hat\rho_k}\) in the update of \refBY{}, for the sake of a neater expression we opted to omit it at the cost of introducing slight conservatism.


\begin{lemma}\label{thm:BY:leq}%
				Suppose that \cref{ass:basic} holds, and consider the iterates generated by Bregman proximal gradient iterations \eqref{eq:BPG} with \(\gamma_k\) and \(\hat\rho_k\) selected according to \refBY.
				Then, both \eqref{eq:rhokhatgeq} and \eqref{eq:BY:rhok*+} are satisfied for any \(k\in\N\).

				Moreover, denoting
				\begin{equation}\label{eq:UkBY}
					\U_k(x)
				\coloneqq
					\D_{\kernel}(x,x^k)
					+
					\gamma_k(1+\hat\rho_k)P_{k-1}(x)
					+
					(1-\tfrac{\rho_k}{2\hat\rho_k})
					\D_{\kernel}(x^k,x^{k-1}),
				\end{equation}
				one has that
				\begin{equation}\label{eq:UkBY:leq}
					\U_{k+1}(x)
				\leq
					\U_k(x)
					-
					\gamma_k(
						\smash{
							\overbrace{1+\hat\rho_k-\rho_{k+1}\hat\rho_{k+1}}^{\geq\hat\rho_k-\rho_k\geq0}
						}
					)P_{k-1}(x)
				\end{equation}
				holds for any \(x\in\dom\varphi\cap\dom\kernel\) and \(k\in\N\).
			\end{lemma}

\begin{proof}
				The update \eqref{eq:BY:rhok*} clearly ensures that \(\rho_{k+1}\leq\hat\rho_{k+1}\) always holds.
				Note that the second element in the minimum within \eqref{eq:BY:rhok*+} coincides with that in \eqref{eq:BY:rhok*};
				moreover, since \(\rho_{k+1}\leq\hat\rho_{k+1}\) one has that
				\(
					\rho_{k+1}\hat\rho_{k+1}
				\leq
					\hat\rho_{k+1}^2
				=
					1+\rho_k
				\leq
					1+\hat\rho_k
				\),
				altogether confirming that the validity of \eqref{eq:BY:rhok*+}.

				Observe further that the bound \(\hat\rho_k\geq\rho_k\) ensures that both elements in the minimum of \eqref{eq:BY:rhok*} are strictly positive, and thus so are the generated stepsizes \(\gamma_k\).
				Finally, \eqref{eq:UkBY:leq} follows from \eqref{eq:UkBYdt:leq} with the specified choices of \(\vartheta_k\) and \(\delta_k\).
			\end{proof}

			In case \(\kernel\) has a symmetry coefficient \(\alpha>0\), we may leverage the bound \eqref{eq:Bk:FNEa} for \(B_{k+1}\).
			By doing so, the inequality \eqref{eq:ineq0} in \cref{thm:eq} becomes
			\begin{multline*}
				\widehat{\U}_{k+1}(x)
			\leq
				\widehat{\U}_k(x)
				-
				\gamma_k(1+\vartheta_k-\rho_{k+1}\vartheta_{k+1})P_{k-1}(x)
			\\
				-
				\left\{
					\tfrac{\alpha_k}{1+\alpha_k}
					-
					\rho_{k+1}
					\left[
						\tfrac{
							(1+\alpha)\delta_{k+1}^2
						}{
							(1+\alpha)\delta_{k+1}-\rho_{k+1}
						}
						\tfrac{1}{2}
						\Lambda_{k,\delta_{k+1}}
						-
						\vartheta_{k+1}(1-\gamma_k\ell_k)
					\right]
				\right\}
				\DD_{\kernel}(x^k,x^{k-1}).
			\end{multline*}

			Once again, we introduce a parameter \(\hat\rho_{k+1}\) (to be specified later) that satisfies \eqref{eq:rhokhatgeq} whilst based on information available at iteration \(k\).
			We can conveniently set \(\delta_{k+1}=\vartheta_{k+1}=\frac{2}{1+\alpha}\hat\rho_{k+1}\), and use the bound
			\(
				(1+\alpha)\delta_{k+1}-\rho_{k+1}
			\geq
				(1+\alpha)\delta_{k+1}-\hat\rho_{k+1}
			\)
			to simplify the coefficient of \(\Lambda_{k,\delta_{k+1}}\).
			Combined with the fact that
			\(
				\tfrac{\alpha_k}{1+\alpha_k}
			\geq
				\tfrac{\alpha}{1+\alpha}
			\),
			the inequality simplifies as
			\begin{align*}
				\U^{\alpha}_{k+1}(x)
			\coloneqq{} &
				\D_{\kernel}(x,x^{k+1})
				+
				\D_{\kernel}(x^{k+1},x^k)
				+
				\gamma_{k+1}\left(1+\tfrac{2}{1+\alpha}\hat\rho_{k+1}\right)P_k(x)
			\\
			\leq{} &
				\U^{\alpha}_k(x)
				-
				\gamma_k(1+\tfrac{2}{1+\alpha}\hat\rho_k-\tfrac{2}{1+\alpha}\hat\rho_{k+1}\rho_{k+1})P_{k-1}(x)
			\\
			&
				-
				\left\{
					\tfrac{\alpha}{1+\alpha}
					-
					\tfrac{2}{1+\alpha}
					\hat\rho_{k+1}
					\rho_{k+1}
					\left[
						\Lambda_{k,\delta_{k+1}}
						-
						(1-\gamma_k\ell_k)
					\right]
				\right\}
				\DD_{\kernel}(x^k,x^{k-1}),
			\end{align*}
			where \(\U^{\alpha}_k(x)\) corresponds to \(\widehat{\U}_k(x)\) as in \cref{thm:eq} with \(\vartheta_k=\tfrac{2}{1+\alpha}\hat\rho_k\).
			By imposing negativity of the coefficients of \(P_{k-1}(x)\) and \(\DD_{\kernel}(x^k,x^{k-1})\) as done in the previous subsection, the following analogue of \cref{thm:BY:leq} for \refFNEa{} is derived.


\begin{lemma}\label{thm:FNEa:leq}%
				Additionally to \cref{ass:basic}, suppose that \(\kernel\) has symmetry coefficient \(\alpha>0\) and consider the iterates generated by Bregman proximal gradient iterations \eqref{eq:BPG} with \(\gamma_k\) and \(\hat\rho_k\) selected according to \refFNEa.
				Then, denoting
				\begin{equation}\label{eq:UkFNEa}
					\U^{\alpha}_k(x)
				\coloneqq
					\D_{\kernel}(x,x^k)
					+
					\D_{\kernel}(x^k,x^{k-1})
					+
					\gamma_k\left(1+\tfrac{2}{1+\alpha}\hat\rho_k\right)P_{k-1}(x),
				\end{equation}
				one has that
				\begin{equation}\label{eq:UkFNEa:leq}
					\U^{\alpha}_{k+1}(x)
				\leq
					\U^{\alpha}_k(x)
					-
					\gamma_k\Bigl(
						\smash{
							\overbrace{
								1+\tfrac{2}{1+\alpha}\hat\rho_k-\tfrac{2}{1+\alpha}\hat\rho_{k+1}\rho_{k+1}
							}^{
								\geq
								\tfrac{2}{1+\alpha}(\hat\rho_k-\rho_k)
								\geq
								0
							}
						}
					\Bigr)P_{k-1}(x)
				\end{equation}
				holds for any \(x\in\dom\varphi\cap\dom\kernel\) and \(k\in\N\).
			\end{lemma}

\begin{lemma}\label{thm:descent}%
			Suppose that \cref{ass:basic} holds, and consider the iterates generated by Bregman proximal gradient iterations \eqref{eq:BPG} with \(\gamma_k\) and \(\hat\rho_k\) selected according to \refBY.
			Then, with \(\U_k\) as in \eqref{eq:UkBY},
			the following hold for any \(x\in\dom\kernel\) satisfying \(\varphi(x)\leq\inf_{k\in\N}\varphi(x^k)\):
			\begin{enumerate}
			\item \label{thm:SD}%
				\(\bigl(\U_k(x)\bigr)_{k\in\N}\) decreases and converges to a finite value.
			\item \label{thm:Pkmin}%
				\(P_K^{\rm min}(x)\leq\frac{\U_0(x)}{\sum_{k=1}^{K+1}\gamma_k}\) for every \(K\geq 1\), where \(P_K^{\rm min}(x)\coloneqq\min_{k\leq K}P_k(x)\).
			\end{enumerate}
			When \(\kernel\) has symmetry coefficient \(\alpha>0\), all remains true for the updates of \refFNEa, with \(\U_k\gets\U^{\alpha}_k\) as in \eqref{eq:UkFNEa}.
		\end{lemma}

\begin{proof}
			See \cref{proof:thm:descent}.
		\end{proof}

\begin{lemma}\label{thm:Lamkto1}%
				Suppose that \cref{ass:basic} holds, and consider a sequence \((x^k)_{k\in\N}\) generated by Bregman proximal gradient iterations \eqref{eq:BPG} with stepsizes \(\gamma_k>0\).
				Suppose that \((x^k)_{k\in\N}\) is contained in a compact set \(\K\subset C\), and consider the ratio
				\[
					\Lambda_{k,\delta_{k+1}}
				=
					\frac{
						2\D_{\kernel^*}\bigl(\nabla\kernel(x^k)+\delta_{k+1}\bigl[H_k(x^k)-H_k(x^{k-1})\bigr],\nabla\kernel(x^k)\bigr)
					}{
						\delta_{k+1}^2
						\DD_{\kernel}(x^k,x^{k-1})
					}
				\]
				as in \eqref{eq:Lamk}, where \((\delta_k)_{k\in\N}\subset\R_{++}\) is a bounded sequence.
				If \(\gamma_k\to0\), then \(\Lambda_{k,\delta_{k+1}}\to1\).
			\end{lemma}

\begin{proof}
				For notational conciseness, let us denote \(u^k\coloneqq\nabla\kernel(x^k)-\nabla\kernel(x^{k-1})\) and \(v^k\coloneqq\nabla f(x^k)-\nabla f(x^{k-1})\), so that \(H_k(x^k)-H_k(x^{k-1})=u^k-\gamma_k v^k\).
				For any \(k\in\N\) there exists
				\(\xi^k\) on the line segment between \(\nabla\kernel(x^k)\) and \(\nabla\kernel(x^k)+\delta_{k+1}(H_k(x^k)-H_k(x^{k-1}))\)
				and
				\(\eta^k\) on the line segment between \(\nabla\kernel(x^k)\) and \(\nabla\kernel(x^{k-1})\)
				such that
				\begin{align}
				\label{eq:Lamknum}
					\Lambda_{k,\delta_{k+1}}
				={} &
					\frac{
						2
						\D_{\kernel^*}\bigl(\nabla\kernel(x^k)+\delta_{k+1}\bigl[H_k(x^k)-H_k(x^{k-1})\bigr],\nabla\kernel(x^k)\bigr)
					}{
						\delta_{k+1}^2
						\DD_{\kernel}(x^k,x^{k-1})
					}
				\\
				\nonumber
				={} &
					\frac{
						\innprod{
							\nabla^2\kernel^*(\xi_k)
							\bigl[H_k(x^k)-H_k(x^{k-1})\bigr]
						}{
							H_k(x^k)-H_k(x^{k-1})
						}
					}{
						\innprod{
							\nabla^2\kernel^*(\eta_k)
							u^k
						}{
							u^k
						}
					}
				\\
				\nonumber
				={} &
					\frac{
						\innprod{
							\nabla^2\kernel^*(\xi_k)
							u^k
						}{
							u^k
						}
					}{
						\innprod{
							\nabla^2\kernel^*(\eta_k)
							u^k
						}{
							u^k
						}
					}
					-
					2\gamma_k
					\frac{
						\innprod{
							\nabla^2\kernel^*(\xi_k)
							u^k
						}{
							v^k
						}
					}{
						\innprod{
							\nabla^2\kernel^*(\eta_k)
							u^k
						}{
							u^k
						}
					}
					+
					\gamma_k^2
					\frac{
						\innprod{
							\nabla^2\kernel^*(\xi_k)
							v^k
						}{
							v^k
						}
					}{
						\innprod{
							\nabla^2\kernel^*(\eta_k)
							u^k
						}{
							u^k
						}
					}.
				\end{align}
				Since \(\kernel\) is twice continuously differentiable with \(\nabla^2\kernel\succ0\) on \(C\), and \(\K\subset C\) is compact and convex, one has that
				\[
				\textstyle
					L_{\kernel,\K}
				\coloneqq
					\sup_{\K}\norm{\nabla^2\kernel}
				=
					\left(\inf_{\nabla\kernel(\K)}\lambda_{\rm min}(\nabla^2\kernel^*)\right)^{-1}
				\]
				is finite (\(L_{\kernel,\K}\) being the Lipschitz modulus of \(\nabla\kernel\) on \(\K\)).
				As such, one has that
				\(
					\innprod{\nabla^2\kernel^*(\eta_k)u^k}{u^k}
				\geq
					L_{\kernel,\K}^{-1}\norm{u^k}^2
				\)
				for all \(k\).
				Moreover, letting \(L_{f,\K}^{\kernel}\) denote a smoothness modulus of \(f\) relative to \(\kernel\) on \(\K\), ensured to exist by \cref{ass:f}, we infer from \cite[Prop. 2.5(ii)]{ahookhosh2021bregman} that
				\(
					\norm{v^k}\leq L_{f,\K}^{\kernel} L_{\kernel,\K}\norm{u^k}
				\)
				holds for all \(k\).
				Therefore,
				\begin{align*}
					\abs{\Lambda_{k,\delta_{k+1}}-1}
				\leq{} &
					\norm{\nabla^2\kernel^*(\xi_k)-\nabla^2\kernel^*(\eta_k)}
					L_{\kernel,\K}
					+
					2\gamma_k
					L_{f,\K}^{\kernel} L_{\kernel,\K}^2
					\norm{\nabla^2\kernel^*(\xi_k)}
				\\
				&
					+
					\gamma_k^2
					L_{\kernel,\K}^3
					(L_{f,\K}^{\kernel})^2
					\norm{\nabla^2\kernel^*(\xi_k)}.
				\end{align*}
				If \(\gamma_k\to0\), then eventually \(\gamma_k<\frac{1}{L_{f,\K}^{\kernel}}\) and standard results ensure that \((x^k)_{k\in\N}\) converges to some point \(x\in\K\).
				In this case, \((\xi^k)_{k\in\N}\) and \((\eta^k)_{k\in\N}\) converge to \(\nabla\kernel(x)\) (the former sequence because \((\delta_k)_{k\in\N}\) is bounded), and by continuity of \(\nabla^2\kernel^*\) on \(\K\) the right-hand side in the above inequality vanishes.
			\end{proof}

\begin{lemma}\label{lem:prox:property:optimal}%
				Additionally to \cref{ass:basic} suppose that \(\argmin_C\varphi\neq\emptyset\).
				Let a sequence \((y^k)_{k\in\N}\) contained in \(C\) and converging to a point \(y^\star\in\argmin_C\varphi\) be fixed, and for every \(k\in\N\) let
				\begin{equation}\label{eq:baryk}
					\bar y^k
				\coloneqq
					\argmin_w\left\{
						g(w)
						+
						\innprod{\nabla f(y^k)}{w-y^k}
						+
						\tfrac{1}{\gamma_{k+1}}\D_{\kernel}(w,y^k)
					\right\}
				\end{equation}
				where \((\gamma_k)_{k\in\N}\) is a bounded sequence of strictly positive stepsizes.
				Then, \(\bar y^k\to y^\star\) and \(\gamma_{k+1}(\varphi(\bar y^k) - \min\varphi)\to0\).
			\end{lemma}

\begin{proof}
				Consider the ``left'' Bregman proximal operator \(\prox_{g}:\interior\dom\kernel\to\dom\kernel\) defined as
				\[
					\prox_{g}(y)
				\coloneqq
					\argmin_{w\in\R^n}\{g(w)+\D_{\kernel}(w,y)\}
				\]
				(note that \(\prox_{g}(y)\in\interior\dom\kernel\subseteq\dom\kernel\) for any \(y\in\interior\dom\kernel\), owing to \cref{ass:basic}).
				The mapping \(\prox_{\gamma_{k+1}g}\circ\nabla\kernel^*\) is \(\nabla\kernel\)-firmly-nonexpansive, in the sense that
				\begin{equation}\label{eq:BPG:FNE}
					\DD_{\kernel}(\bar y_1,\bar y_2)
				\leq
					\innprod{\eta_1-\eta_2}{\bar y_1-\bar y_2}
				\end{equation}
				holds for any \(\eta_i\in\R^2\) and \(\bar y_i = \prox_{\gamma_{k+1} g}\circ\nabla\kernel^*(\eta_i)\), \(i=1,2\);
				a proof of this fact can be found in \cite[Lem. 4.2]{wang2022bregman} (see also \cite[Thm. 4.9]{wang2025bregman} for its \emph{equivalence} to convexity of \(g\)).
				Note that \eqref{eq:baryk} can equivalently be written as
				\[
					\bar y^k
				=
					\prox_{\gamma_{k+1} g}\circ\nabla\kernel^*(H_{k+1}(y^k)),
				\]
				where we remind that \(H_{k+1}=\nabla\kernel-\gamma_{k+1}\nabla f\).
				Using \(\nabla\kernel\)-firm nonexpansiveness and recalling that \(y^\star = \prox_{\gamma_{k+1} g}\circ\nabla\kernel^*(H_{k+1}(y^\star))\) we have
				\begin{align*}
					\DD_{\kernel}(\bar y^k,y^\star)
				\stackrel{\text{\clap{\eqref{eq:BPG:FNE}}}}{\leq}{} &
					\innprod{H_{k+1}(y^k) - H_{k+1}(y^\star)}{\bar y^k - y^\star}
				\\
				\leq{} &
					\Bigl(
						\norm{\nabla \kernel(y^k) - \nabla \kernel(y^\star)}
						+
						\gamma_{k+1}\norm{\nabla f(y^k) - \nabla f(y^\star)}
					\Bigr)
					\norm{\bar y^k - y^\star},
				\end{align*}
				which vanishes as \(k\to\infty\).
				Then, by essential strict convexity of \(\kernel\), it follows that \(\bar y^k\to y^\star\).
				Moreover, by the subgradient inequality, for every \(k \in \N\) it holds that
				\begin{align*}
					0
				\leq
					\gamma_{k+1}(\varphi(\bar y^k) - \min\varphi)
				={} &
					\gamma_{k+1}(f(\bar y^k) + g(\bar y^k) - \min\varphi)\\
				\leq{} &
					\gamma_{k+1}(f(\bar y^k) - f(y^\star))
				\\
				&
					-\innprod{\nabla \kernel(y^k) - \gamma_{k+1}\nabla f(y^k) - \nabla \kernel(\bar y^k)}{y^\star - \bar y^k}.
				\end{align*}
				The proof then follows from continuity of \(f\) and the fact that the inner product vanishes, since both \(y^k\) and \(\bar y^k\) converge to \(y^\star\).
			\end{proof}

\begin{theorem}\label{thm:xinC}%
				Additionally to \cref{ass:basic}, suppose that
				\begin{equation}\label{eq:xinC}
					\text{there exists \(x\in C\) such that \(\varphi(x)\leq\inf_{k\in\N}\varphi(x^k)\)}
				\end{equation}
				holds for the iterates \(x^k\) generated by \refBY.
				Then, the sequence \((x^k)_{k\in\N}\) converges to a solution \(x^\star\in\argmin_C\varphi\neq\emptyset\) and \(\varphi(x^k)\to\inf_{\overline C}\varphi\).

				When \(\kernel\) has symmetry coefficient \(\alpha>0\), the same is true for \refFNEa.
			\end{theorem}

			The fact that this result subsumes \cref{thm:main:C} is obvious by observing that the validity of \cref{thm:xinC} implies that any \(x\) complying with \eqref{eq:xinC} must necessarily belong to \(\argmin_{\overline C}\varphi\cap C\).
			The proof of \cref{thm:xinC} will be carried out via intermediate claims.
			In what follows, we consider \(\U_k\) as in \eqref{eq:UkBY} in case of \refBY{}; under the needed symmetry assumption, the same proof applies to \refFNEa{} as well by simply replacing \(\U_k\gets\U^{\alpha}_k\).


\begin{claim}\label{thm:xinC:boundedseq}
				There exists a compact set \(\K\subset C\) containing all the iterates \(x^k\).
			\end{claim}

\begin{proof}
				In view of \eqref{eq:xinC}, \cref{thm:SD} implies that
				\[
					\D_{\kernel}(x,x^k)
				\leq
					\U_k(x)
				\leq
					\U_0(x)
				\]
				holds for any \(k\in\N\).
				The assertion then follows from \cref{fact:D:coercive}.
			\end{proof}

\begin{claim}
				\(\gamma_k\not\to0\).
			\end{claim}

\begin{proof}
				To arrive to a contradiction, suppose that \(\gamma_k\to0\).
				Then, \cref{thm:Lamkto1} implies that eventually the quantity
				\(
					[\Lambda_{k,\delta}-(1-\gamma_k\ell_k)]_+
				\)
				appearing in both \eqref{eq:BY:rhok*} and \eqref{eq:FNEa:rhok*} vanishes.
				Since \((x^k)_{k\in\N}\) is bounded and bounded away from the boundary of \(C\), regardless of whether or not \(\kernel\) has a symmetry coefficient \(\alpha>0\), it holds that \(\inf_{k\in\N}\alpha_k>0\);
				furthermore, for both \refBY{} and \refFNEa{} note that \(\hat\rho_{k+1}\leq\sqrt{1+\rho_k}\leq\sqrt{1+\hat\rho_k}\), implying that \(\hat\rho_k\leq\frac{1+\sqrt{5}}{2}\) holds for any \(k\).
				As such, in both \eqref{eq:BY:rhok*} and \eqref{eq:FNEa:rhok*} eventually the second element in the minimum is infinite, implying that the update reduces to \(\gamma_{k+1}=\hat\rho_{k+1}\gamma_k\) and is thus divergent, a contradiction.
			\end{proof}

\begin{claim}
				\(\inf_{k\in\N}\varphi(x^k)=\inf_{\overline C}\varphi\) (in particular, necessarily \(x\in\argmin_C\varphi\) for any \(x\) satisfying \eqref{eq:xinC}).
			\end{claim}

\begin{proof}
				Having shown that \(\gamma_k\not\to0\), one has that \(\sum_{k\in\N}\gamma_k=\infty\).
				\Cref{thm:Pkmin} then implies that \(\inf_{k\in\N}\varphi(x^k)=\varphi(x)\).
				From the arbitrariness of the point \(x\) as in \eqref{eq:xinC} we conclude that necessarily \(x\in\argmin_C\varphi\subseteq\argmin_{\overline C}\varphi\), with inclusion holding by virtue of \cite[Prop. 11.1(iv)]{bauschke2017convex}.
				Hence \(\inf_{k\in\N}\varphi(x^k)=\inf_{\overline C}\varphi\).
			\end{proof}

\begin{claim}\label{claim:unique}%
				There exists exactly one optimal limit point \(x^\star\in\argmin_C\varphi\).
			\end{claim}

\begin{proof}
				The existence of an optimal limit point is guaranteed by the previous claim, since \((x^k)_{k\in\N}\) is bounded (and bounded away from the boundary of \(C\)) and \(\varphi\) is lsc.
				Consider two optimal limit points \(\bar x_1\) and \(\bar x_2\), and two corresponding subsequences \((x^k)_{k\in K_1}\to\bar x_1\) and \((x^k)_{k\in K_2}\to\bar x_2\).
				Notice that
				\[
					\U_k(\bar x_1)-\U_k(\bar x_2)
				=
					\D_{\kernel}(\bar x_1,x^k)-\D_{\kernel}(\bar x_2,x^k)
				\]
				converges to some finite value \(V\), because both \(\U_k(\bar x_1)\) and \(\U_k(\bar x_2)\) are convergent.
				Considering the limits along \(k\in K_1\) and \(k\in K_2\) yields that
				\[
					V
				=
					\D_{\kernel}(\bar x_1,\bar x_1)-\D_{\kernel}(\bar x_2,\bar x_1)
				=
					\D_{\kernel}(\bar x_1,\bar x_2)-\D_{\kernel}(\bar x_2,\bar x_2),
				\]
				hence that \(-\D_{\kernel}(\bar x_2,\bar x_1)=\D_{\kernel}(\bar x_1,\bar x_2)\).
				Thus \(\DD_{\kernel}(\bar x_1,\bar x_2)=0\), implying that \(\bar x_1=\bar x_2\).
			\end{proof}

			In light of the previous claim, the proof of \cref{thm:xinC} is completed once we show that \(x^k\to x^\star\).
			To this end, owing to the fact that \(\D_{\kernel}(x^\star,x^k)\leq\U_k(x^\star)\) it will suffice to show that \(U\coloneqq\lim_{k\to\infty}\U_k(x^\star)\) is zero, (existence and finiteness of \(U\) is ensured by \cref{thm:SD}).
			\begin{itemize}
			\item
				Let us consider a subsequence \((x^k)_{k\in K}\) converging to \(x^\star\).
				If the corresponding subsequence \((\gamma_{k+1})_{k\in K}\) is bounded, then it follows from \cref{lem:prox:property:optimal} that  \(x^{k+1}\to x^\star\) and \(\gamma_{k+1} P_k(x^\star) \to 0\) as well, and from the expression of \(\U_k\) together with the fact that \(\hat\rho_{k+1}\) is bounded and \(\inf_k \alpha_k>0\), it is clear that
				\(\U_{k+1}(x^\star)\to0\) as \(K\ni k\to\infty\).

			\item
				In what follows, let us instead consider the complementary case in which for any subsequence \(x^k\) converging to \(x^\star\) the corresponding subsequence of stepsizes \((\gamma_{k+1})_{k\in K}\) is divergent.
				In this case, note that since \(\gamma_{k+1}P_k(x^\star)\leq\U_{k+1}(x^\star)\leq\U_0(x^\star)\), we have
				\begin{align}
				\nonumber
					(x^k)_{k\in K}\to x^\star
				\Leftrightarrow{} &
					(\gamma_{k+1})_{k\in K}\to\infty
				\Leftrightarrow
					\bigl(P_k(x^\star)\bigr)_{k\in K}\to0
				\\
				\nonumber
				\Rightarrow{} &
					(\gamma_k)_{k\in K}\to\infty
				\\
				\Leftrightarrow{} &
					(x^{k-1})_{k\in K}\to x^\star
				\Leftrightarrow
					\bigl(P_{k-1}(x^\star)\bigr)_{k\in K}\to0,
				\label{eq:gamk:infty"gamk-1}
				\end{align}
				where the right implication follows from the fact that \(\gamma_{k+1}\leq\hat\rho_{k+1}\gamma_k\leq\rho_{\rm max}\gamma_k\), for some \(\rho_{\rm max}\leq\frac{1+\sqrt{5}}{2}\).
				Since an optimal limit exists, it follows that \(\sup_{k\in\N}\gamma_k=\infty\).

				In what follows, we construct a specific subsequence \(K\coloneqq\{k_0,k_1,\dots\}\) along which \((\gamma_k)_{k\in K}\) diverges.
				In doing so, we expand upon the arguments in the proof of \cite[Thm. 2.3]{latafat2024adaptive} to account for the complications of the non-Euclidean setting investigated here.
				For \(i\geq0\) let
				\begin{equation}\label{eq:ki+}
					k_{i+1}=\min\{k\geq k_i \mid \gamma_k \geq \rho_{\rm max}\gamma_{k_i}\}.
				\end{equation}
				Then, \(\bigl(\gamma_{k_i}\bigr)_{i\in\N}\to\infty\), which by \eqref{eq:gamk:infty"gamk-1} implies that
				\begin{equation}\label{eq:xkitox*}
					\lim_{i\to\infty}x^{k_i-s}
				=
					x^\star
				\quad
					\forall s=1,2,3
				\end{equation}
				(in fact, for any \(s\in\N\)).
				In light of \cref{thm:SD} we have that
				\begin{equation}\label{eq:U:gamkPk-1}
					U= \lim_{k \to \infty} \U_k= \lim_{i \to \infty} \U_{k_i-1}(x^\star) = \lim_{i \to \infty} \gamma_{k_i-1}(1+ \vartheta_{k_i-1})P_{k_i-2}(x^\star).
				\end{equation}

				We proceed to show that \(\gamma_{k-1} P_{k-2}(x^\star)\) converges to zero along the same subsequence.
				\begin{subequations}
					For every \(i\in\N\), note that
					\begin{gather}
						\rho_{k_i}>1
						~\text{ and }~
						k_{i-1}\leq k_i-1
					\shortintertext{by minimality of \(k_i\) and the fact that \(\rho_{\rm max}>1\), hence that}
					\label{eq:k_i-1}
						\text{either }~
						\rho_{k_i-1}>1
						~\text{ or }~
						\bigl(
							k_i-1\notin K
							\text{ and thus }
							k_{i-1}\leq k_i-2
						\bigr).
					\shortintertext{These combined imply also that}
					\label{eq:k-1}
						\rho_{k_i-1}\geq\rho_{\rm max}^{-1}.
					\end{gather}
					Indeed, if not, then \(\rho_{k_i-1}<\rho_{\rm max}^{-1}<1\), implying by \eqref{eq:k_i-1} that \(k_{i-1}\leq k_i-2\);
					this would lead to the contradiction
					\[
						\rho_{\rm max}\gamma_{k_{i-1}}
					\stackrel{\text{\clap{\eqref{eq:ki+}}}}{\leq}
						\gamma_{k_i}
					\leq
						\rho_{\rm max}\gamma_{k_i-1}
					=
						\rho_{\rm max}\rho_{k_i-1}\gamma_{k_i-2}
					\stackrel{\mathclap{\bot}}{<}
						\gamma_{k_i-2}
					\leq
						\rho_{\rm max}\gamma_{k_{i-1}},
					\]
					where ``\(\bot\)'' marks where the contradictory inequality is used, and the last inequality follows both in case \(k_i-2=k_{i-1}\) (since \(\rho_{\rm max}>1\)) or when \(k_{i-1}<k_i-2<k_i\) (from minimality in the definition of \(k_i\)).
				\end{subequations}
				Therefore, \eqref{eq:k-1} holds true, implying in particular that the sequence
				\begin{equation}\label{eq:Lambda:k-2:bounded}
					\bigl(\Lambda_{k_i-2, 2\hat\rho_{k_i-1}}\bigr)_{i\in\N}
				\quad
					\text{is bounded,}
				\end{equation}
				for otherwise the second term in either \eqref{eq:BY:rhok*} or \eqref{eq:FNEa:rhok*} would vanish, owing to the fact that \(\hat\rho_k\) is lower bounded by \(\sqrt{1/2}\) and similarly \(\alpha_k\) is bounded away from zero.

				Let \(v^k\coloneqq H_k(x^{k-1})- H_k(x^k)\in\gamma_k\partial\varphi(x^k)\), and observe that
				\begin{align*}
				&
					\gamma_k P_{k-1}(x^\star)
				\\
				\leq{} &
					\rho_k\innprod{x^\star - x^{k-1}}{-v^{k-1}}
				\\
				\leq{} &
					\tfrac{\rho_k}{2\hat\rho_k}\D_{\kernel}(x^\star, x^{k-1})
					+
					\tfrac{\rho_k}{2\hat\rho_k}
					\D_{\kernel^*}\bigl(\nabla\kernel(x^{k-1})-2\hat\rho_kv^{k-1}\bigr), \nabla \kernel(x^{k-1})\bigr)
				\\
				={} &
					\tfrac{\rho_k}{2\hat\rho_k}\D_{\kernel}(x^\star, x^{k-1})
					+
					2\rho_k \hat\rho_k^2\Lambda_{k-1, 2\hat\rho_k} \DD_{\kernel}(x^{k-1},x^{k-2})
				\\
				\leq{} &
					\tfrac{1}{2}\D_{\kernel}(x^\star, x^{k-1})
					+
					2\rho_{\rm max}^3 \Lambda_{k-1, 2\hat\rho_k} \DD_{\kernel}(x^{k-1},x^{k-2})
				\end{align*}
				holds for any \(k\), where we used the Bregman--Young inequality \eqref{eq:BY} with parameter \(\delta= \hat\rho_k\) in the second inequality, and \(\rho_k\leq \hat\rho_k\leq \rho_{\rm max}\) in the last one.
				Recall that \(\bigl(x^{k_i-3}\bigr)_{i\in\N} \to x^\star\) by \eqref{eq:xkitox*}.
				Thus,
				\[
					\gamma_{k_i-1} P_{k_i-2}(x^\star)
				\leq
					\tfrac{1}{2}
					\underbrace{
						\D_{\kernel}(x^\star, x^{k_i-2})
						\vphantom{\Lambda_{k_i-2, 2\rho_{k_i-1}}}
					}_{\to 0 \text{ by \eqref{eq:xkitox*}}}
					+
					2\rho_{\rm max}^3
					\underbrace{
						\Lambda_{k_i-2, 2\rho_{k_i-1}}
					}_{\text{\rm bounded}}
					\,
					\underbrace{
						\DD_{\kernel}(x^{k_i-2},x^{k_i-3})
						\vphantom{\Lambda_{k_i-2, 2\rho_{k_i-1}}}
					}_{\to 0 \text{ by \eqref{eq:xkitox*}}}.
				\]
				Using this in \eqref{eq:U:gamkPk-1} and noting that \(\theta_{k_i-1}\) being a multiple of \(\hat{\rho}_{k_i-1}\) in both \refBY{} and \refFNEa{} is bounded, completes the proof.
			\end{itemize}


\subsection{Proof of \texorpdfstring{\cref{eq:main:inf}}{Equation \ref*{eq:main:inf}}}
			In this subsection we prove that the iterates generated by either \refBY{} or \refFNEa{} in the generality of \cref{ass:basic} (in addition to \(\kernel\) having a symmetry coefficient \(\alpha>0\) in the latter case) are such that \(\inf_{k\in\N}\varphi(x^k)=\inf_{\overline C}\varphi\).

			To see this, contrary to the claim suppose that \(\inf_{k\in\N}\varphi(x^k)>\inf_{\overline C}\varphi\).
			Then, since \(\inf_{\overline C}\varphi=\inf_C\varphi\) by \cite[Prop. 11.1(iv)]{bauschke2017convex}, there exists \(x\in C\) such that \(\varphi(x^k)\geq\varphi(x)\) holds for all \(k\in\N\).
			Invoking \cref{thm:xinC} yields a contradiction.



