\begin{proof}[\textbf{Proof of \cref{thm:eq}}]%
			Based on the subgradient characterization \eqref{eq:subgradvarphi} and the definition of \(\ell_k\) in \eqref{eq:lk}, we have
			\begin{align}
			\nonumber
				0
			={} &
				\varphi(x^{k-1})
				-
				\varphi(x^k)
				-
				\tfrac{1}{\gamma_k}
				\innprod{H_k(x^{k-1})-H_k(x^k)}{x^{k-1}-x^k}
				-
				\tD_\varphi(x^{k-1},x^k)
			\\
			={} &
				P_{k-1}(x)
				-
				P_k(x)
				-
				\tfrac{1-\gamma_k\ell_k}{\gamma_k}
				\DD_{\kernel}(x^k,x^{k-1})
				-
				\tD_\varphi(x^{k-1},x^k).
			\label{eq:thetk}
			\end{align}
			Furthermore, by leveraging the subgradient characterization \eqref{eq:subgrad} and applying the three point identity of \cref{thm:3p},
			\begin{align}
			\nonumber
				0
			={} &
				g(x)-g(x^{k+1})-\innprod{\tilde{\nabla}g(x^{k+1})}{x-x^{k+1}}-\tD_g(x,x^{k+1})
			\\
			\nonumber
			={} &
				g(x)-g(x^{k+1})
				+
				\innprod{\nabla f(x^k)}{x- x^{k+1}}
			\\
			\nonumber
			&
				-
				\tfrac{1}{\gamma_{k+1}}\innprod{\nabla\kernel(x^k)-\nabla\kernel(x^{k+1})}{x-x^{k+1}}
				-
				\tD_g(x,x^{k+1})
			\\
			\nonumber
			={} &
				g(x)-g(x^{k+1})
				+
				\underbracket[0.5pt]{
					\innprod{\nabla f(x^k)}{x- x^{k+1}}
				}_{\text{(A)}}
				-
				\tD_g(x,x^{k+1})
			\\
			&
				+
				\tfrac{1}{\gamma_{k+1}}\D_{\kernel}(x,x^k)
				-
				\tfrac{1}{\gamma_{k+1}}\D_{\kernel}(x,x^{k+1})
				-
				\tfrac{1}{\gamma_{k+1}}\D_{\kernel}(x^{k+1},x^k).
			\label{eq:main}
			\end{align}
			We next proceed to expand the term (A) as
			\begin{align*}
				\text{(A)}
			={} &
				\innprod{\nabla f(x^k)}{x-x^k}
				-
				\innprod{\nabla f(x^k)}{x^{k+1}-x^k}
			\\
			={} &
				\innprod{\nabla f(x^k)}{x-x^k}
				+
				\tfrac{1}{\gamma_k}
				\innprod{H_k(x^{k-1})-\nabla\kernel(x^k)}{x^{k+1}-x^k}
			\\
			&
				+
				\tfrac{1}{\gamma_k}
				\innprod{H_k(x^{k-1})-H_k(x^k)}{x^k-x^{k+1}}
			\\
			={} &
				\Bigl[
					f(x)-f(x^k)-\D_f(x,x^k)
				\Bigr]
				+
				\Bigl[
					g(x^{k+1})-g(x^k)-\tD_g(x^{k+1},x^k)
				\Bigr]
			\\
			&
				+
				\tfrac{1}{\gamma_{k+1}}
				B_{k+1},
			\end{align*}
			which combined with \eqref{eq:main} gives
			\begin{align*}
				0
			={} &
				-P_k(x)
				+
				\tfrac{1}{\gamma_{k+1}}\D_{\kernel}(x,x^k)
				-
				\tfrac{1}{\gamma_{k+1}}\D_{\kernel}(x,x^{k+1})
				-
				\tfrac{1}{\gamma_{k+1}}\D_{\kernel}(x^{k+1},x^k)
			\\
			&
				-\D_f(x,x^k)
				-\tD_g(x^{k+1},x^k)
				+
				\tfrac{1}{\gamma_{k+1}}
				B_{k+1}
				-
				\tD_g(x,x^{k+1}).
			\end{align*}
			We may now add \eqref{eq:main} to \eqref{eq:thetk} scaled by \(\vartheta_{k+1}\) and multiply everything by \(\gamma_{k+1}\) to obtain
			\begin{align*}
				0
			={} &
				-\gamma_{k+1} P_k(x)
				+
				\D_{\kernel}(x,x^k)
				-
				\D_{\kernel}(x,x^{k+1})
				-
				\D_{\kernel}(x^{k+1},x^k)
			\\
			&
				-
				\gamma_{k+1}\D_f(x,x^k)
				-
				\gamma_{k+1}\tD_g(x^{k+1},x^k)
				+
				B_{k+1}
				-
				\gamma_{k+1}\tD_g(x,x^{k+1})
			\\
			&
				+
				\gamma_{k+1}\vartheta_{k+1}\left(
					P_{k-1}(x)
					-
					P_k(x)
					-
					\tfrac{1-\gamma_k\ell_k}{\gamma_k}
					\DD_{\kernel}(x^k,x^{k-1})
					-
					\tD_\varphi(x^{k-1},x^k)
				\right).
			\end{align*}
			After suitably rearranging, the claimed identity is obtained.

			The inequality follows by neglecting the terms between curly brackets, and further using the identity \(\D_{\kernel}(x^k,x^{k-1})=\frac{\alpha_k}{1+\alpha_k}\DD_{\kernel}(x^k,x^{k-1})\).
		\end{proof}

\begin{proof}[\textbf{Proof of \cref{thm:descent}}]%
			It suffices to prove the claim for \refBY; the case of \refFNEa{} under the needed assumptions follows by simply replacing \(\U_k\gets\U^{\alpha}_k\).
			The assumption on \(x\) ensures that \(P_k(x)\geq0\) holds for all \(k\), implying both that \(\U_k(x)\geq0\) and the claimed monotonic decrease of \(\bigl(\U_k(x)\bigr)_{k\in\N}\) with finite limit by virtue of \cref{thm:BY:leq,thm:FNEa:leq}.
			More precisely, one has that
			\[
				0
			\leq
				\U_{k+1}(x)
			\leq
				\U_k(x)
				-
				\gamma_k(1+q\hat\rho_k-q\hat\rho_{k+1}\rho_{k+1})P_{k-1}(x),
			\]
			where \(q=1\) for \refBY{} and \(q=\frac{1+\alpha}{2\alpha}\) for \refFNEa{}.
			A telescoping argument yields that
			\begin{align*}
				P_K^{\min}(x)
				\sum_{k=1}^K
				\gamma_k(1+q\hat\rho_k-q\hat\rho_{k+1}\rho_{k+1})
			\leq{} &
				\sum_{k=1}^K
				\gamma_k(1+q\hat\rho_k-q\hat\rho_{k+1}\rho_{k+1})P_{k-1}(x)\\
			\leq{} &
				\U_1(x) - \U_{K+1}(x)\\
			\leq{} &
				\U_1(x) - \gamma_{K+1}(1+q\hat\rho_{K+1})P_K^{\rm min}(x),
			\end{align*}
			hence that
			\begin{align*}
				P_K^{\min}(x)
			\leq{} &
				\frac{\U_1(x)
					}{
					\sum_{k=1}^K(\gamma_k + q\gamma_k\hat\rho_k- q\gamma_{k+1}\hat\rho_{k+1}) + \gamma_{K+1} + q\gamma_{K+1}\hat\rho_{K+1}
					}\\
			\leq{} &
				\frac{\U_1(x)
					}{
					\gamma_1\hat\rho_1
					+
					\sum_{k=1}^{K+1}\gamma_k
					}.
			\end{align*}
			Since \(\U_1(x)\leq\U_0(x)\), the claimed inequality follows.
		\end{proof}

