To ease the subsequent discussion, we introduce some convenient notational shorthands and remind some of those already encountered.
Relative to the iterates generated by \eqref{eq:BPG}, for any \(k\in\N\) and \(x\in\dom\varphi\) we denote
\begin{align}
\label{eq:Pk}
	P_k(x)
\coloneqq{} &
	\varphi(x^k)-\varphi(x)
\shortintertext{and}
\label{eq:Bk}
	B_{k+1}
\coloneqq{} &
	\rho_{k+1}
	\innprod{x^{k+1}-x^k}{H_k(x^k)-H_k(x^{k-1})},
\end{align}
where \(\rho_{k+1}=\tfrac{\gamma_{k+1}}{\gamma_k}\) and
\begin{equation}\label{eq:H:def}
	H_k\coloneqq\nabla\kernel-\gamma_k\nabla f
\end{equation}
is the ``forward'' operator.
Due to convexity of \(g\), the BPG updates in \eqref{eq:BPG} are characterized by the subgradient inclusion
\begin{subequations}
	\begin{align}
	\label{eq:subgrad}
		\tilde{\nabla}g(x^{k+1})
	\coloneqq{} &
		\tfrac{\nabla\kernel(x^k)-\nabla\kernel(x^{k+1})}{\gamma_{k+1}}
		-
		\nabla f(x^k)
	\in
		\partial g(x^{k+1}).
	\intertext{%
		Throughout, we use the notation \(\tilde{\nabla}g(x^{k+1})\) to indicate this particular element of the subgradient of \(g\) along the iterates.
		Similarly, we use
	}
	\nonumber
		\tilde{\nabla}\varphi(x^{k+1})
	\coloneqq{} &
		\tilde{\nabla} g(x^{k+1})
		+
		\nabla f(x^{k+1})
	\\
	\label{eq:subgradvarphi}
	={} &
		\tfrac{H_{k+1}(x^k)-H_{k+1}(x^{k+1})}{\gamma_{k+1}}
	\in
		\partial\varphi(x^{k+1}).
	\end{align}
\end{subequations}
In light of these, we adopt the notation
\begin{gather*}
	\tD_g(w,x^k)
\coloneqq
	g(w)-g(x^k)-\innprod{\tilde{\nabla}g(x^k)}{w-x^k},
\shortintertext{and similarly}
	\tD_{\varphi}(w,x^k)
\coloneqq
	{\varphi}(w)-{\varphi}(x^k)-\innprod{\tilde{\nabla}{\varphi}(x^k)}{w-x^k},
\end{gather*}
which are both positive quantities for any \(k\in\N\) and \(w\in\R^n\).

\begin{fact}\label{fact:D}%
					Let \(\kernel:\R^n\to\Rinf\) be of Legendre type, and let \(C\coloneqq\interior\dom\kernel\).
					\begin{enumerate}
					\item \label{fact:D:coercive}%
							{\upshape \cite[Prop. 2.16]{bauschke1997legendre}, \cite[Thm. 3.7(vi)]{bauschke1997legendre}}
							If \(\kernel\) is 1-coercive, then \(\dom\kernel^*=\R^n\) and \(\D_{\kernel}(x,{}\cdot{})\) is coercive for any \(x\in C\).

					\item \label{fact:D:boundary}%
						{\upshape \cite[Thm. 3.8(i)]{bauschke1997legendre}}
						If a sequence \((x^k)_{k\in\N}\) converges to a boundary point of \(C\), then \(\D_{\kernel}(x,x^k)\to\infty\) for any \(x\in C\).

					\item \label{fact:D:solodov}%
						{\upshape \cite[Thm. 2.4]{solodov2000inexact}}
						Suppose that \(\dom\kernel\) is closed and that \(\D_{\kernel}(x^k,y^k)\to0\).
						If either \((x^k)_{k\in\N}\) or \((y^k)_{k\in\N}\) converges, then the other sequence too converges to the same limit.

					\item \label{fact:D:Dphi*}%
						{\upshape \cite[Thm. 26.5]{rockafellar1970convex}}
						The conjugate \(\kernel^*\) is continuously differentiable and strictly convex on \(\interior\dom\kernel^*\), with \(\nabla\kernel^* = \nabla\kernel^{-1}:\interior\dom\kernel^*\to\interior\dom\kernel\).

					\item \label{fact:D:DtoD*}%
						{\upshape \cite[Thm. 3.7(v)]{bauschke1997legendre}}
						\(\D_{\kernel}(x,y) = \D_{\kernel^*}(\nabla \kernel(y), \nabla \kernel(x))\) for any \(x,y\in C\).
					\end{enumerate}
				\end{fact}

\begin{theorem}[summary of main results]\label{thm:main}%
					Suppose that \cref{ass:basic} holds, and consider the iterates generated by \refBY{}.
