\begin{lemma}[Young's inequality in the Bregman sense]\label{thm:BY}%
				Let \(\kernel:\R^n\to\Rinf\) be Legendre (not necessarily 1-coercive).
				Then, for any \(x\in\dom\kernel\), \(y\in\interior\dom\kernel\), \(v\in\R^n\), and \(\delta>0\) one has
				\begin{equation}\label{eq:BY}
					\innprod{x-y}{v}
				\leq
					\tfrac{1}{\delta}
					\D_{\kernel}(x,y)
					+
					\tfrac{1}{\delta}
					\D_{\kernel^*}\bigl(\nabla\kernel(y)+\delta v,\nabla\kernel(y)\bigr).
				\end{equation}
			\end{lemma}

\begin{proof}
				Without loss of generality we may assume that \(\nabla\kernel(y)+\delta v\in\dom\kernel^*\), for otherwise the right-hand side of \eqref{eq:BY} is infinite and the inequality trivializes.
				Since \(\nabla\kernel(y)\in\interior\dom\kernel^*\) by \cref{fact:D:Dphi*}, for any \(t\in(0,1)\) one has that
				\(
					\nabla\kernel(y)+t\delta v\in\interior\dom\kernel^*
				\)
				by \cite[Prop. 3.44]{bauschke2017convex}.
				We have
				\begin{align*}
					\innprod{x-y}{v}
				={} &
					\tfrac{1}{t\delta}
					\innprod{x-y}{t\delta v}
				\\
				={} &
					\tfrac{1}{t\delta}
					\innprod{x-y}{\nabla\kernel(\nabla\kernel^*\bigl(\nabla\kernel(y)+t\delta v)\bigr)-\nabla\kernel(y)}
				\\
				={} &
					\tfrac{1}{t\delta}
					\D_{\kernel}(x,y)
					+
					\tfrac{1}{t\delta}
					\D_{\kernel}\bigl(y,\nabla\kernel^*\bigl(\nabla\kernel(y)+t\delta v\bigr)\bigr)
				\\
				&
					-
					\tfrac{1}{t\delta}
					\D_{\kernel}\bigl(x,\nabla\kernel^*\bigl(\nabla\kernel(y)+t\delta v\bigr)\bigr)
				\\
				\leq{} &
					\tfrac{1}{t\delta}
					\D_{\kernel}(x,y)
					+
					\tfrac{1}{t\delta}
					\D_{\kernel^*}\bigl(\nabla\kernel(y)+t\delta v,\nabla\kernel(y)\bigr).
			\end{align*}
				The second equality follows from Legendreness of \(\kernel\) via \cref{fact:D:Dphi*}, and the third one is the three point identity of \cref{thm:3p}.
				The inequality follows from \cref{fact:D:DtoD*} and the fact that \(\D_\kernel\geq0\).
				By taking the limit as \(t\to1^-\) and appealing to \cite[Thm. 7.5]{rockafellar1970convex}, the claimed inequality \eqref{eq:BY} is obtained.
			\end{proof}

