\begin{lemma}\label{thm:FNE}
					Let \(\kernel:\R^n\to\Rinf\) be Legendre, and \(f,g:\R^n\to\Rinf\) be proper, lsc, and convex, with \(f\) differentiable on \(C\coloneqq\interior\dom\kernel\) and \(\dom g\cap C\neq\emptyset\).
					Then, denoting \(H_k\coloneqq\nabla\kernel-\gamma_k\nabla f\), Bregman proximal gradient iterations \eqref{eq:BPG} with stepsizes \(\gamma_k>0\) and starting at some \(x^0\in C\) satisfy
					\[
						B_{k+1}
					\coloneqq
						\tfrac{\gamma_{k+1}}{\gamma_k}
						\innprod{x^{k+1}-x^k}{H_k(x^k)-H_k(x^{k-1})}
					\geq
						\DD_{\kernel}(x^{k+1},x^k)
					\quad
						\forall k\geq 1.
					\]
				\end{lemma}

\begin{proof}
					Follows by observing that
					\begin{align*}
					&
						\tfrac{\gamma_{k+1}}{\gamma_k}
						\bigl(H_k(x^k)-H_k(x^{k-1})\bigr)
					\\
					={} &
						\nabla\kernel(x^{k+1})-\nabla\kernel(x^k)
						+
						\gamma_{k+1}
						\Bigl[
							\smash{
								\overbrace{
									\tfrac{H_{k+1}(x^k)-\nabla\kernel(x^{k+1})}{\gamma_{k+1}}
								}^{\tilde{\nabla}g(x^{k+1})}
								-
								\overbrace{
									\tfrac{H_k(x^{k-1})-\nabla\kernel(x^k)}{\gamma_k}
								}^{\tilde{\nabla}g(x^k)}
							}
						\Bigr],
					\end{align*}
					hence that
					\(
						B_{k+1}
					=
						\DD_{\kernel}(x^{k+1},x^k)
						+
						\gamma_{k+1}\tD_g(x^{k+1},x^k)
					\geq
						\DD_{\kernel}(x^{k+1},x^k)
					\).
				\end{proof}

Follows by observing that
\begin{align*}
&
	\tfrac{\gamma_{k+1}}{\gamma_k}
	\bigl(H_k(x^k)-H_k(x^{k-1})\bigr)
\\
={} &
	\nabla\kernel(x^{k+1})-\nabla\kernel(x^k)
	+
	\gamma_{k+1}
	\Bigl[
		\smash{
			\overbrace{
				\tfrac{H_{k+1}(x^k)-\nabla\kernel(x^{k+1})}{\gamma_{k+1}}
			}^{\tilde{\nabla}g(x^{k+1})}
			-
			\overbrace{
				\tfrac{H_k(x^{k-1})-\nabla\kernel(x^k)}{\gamma_k}
			}^{\tilde{\nabla}g(x^k)}
		}
	\Bigr],
\end{align*}

We may thus complement \eqref{eq:Bk:BY} with a lower bound as
\begin{align*}
	\DD_{\kernel}(x^{k+1},x^k)
\leq{} &
	B_{k+1}
\\
\leq{} &
	\tfrac{\rho_{k+1}}{\delta_{k+1}}\D_{\kernel}(x^{k+1},x^k)
	+
	\tfrac{\delta_{k+1}\rho_{k+1}}{2}
	\Lambda_{k,\delta_{k+1}}
	\DD_{\kernel}(x^k,x^{k-1}).
\end{align*}
If \(\kernel\) has symmetry coefficient \(\alpha>0\) as in \eqref{eq:alpha}, then note that
\[
	\DD_{\kernel}(x^{k+1},x^k)
\geq
	(1+\alpha)\D_{\kernel}(x^{k+1},x^k).
\]
Combined with the previous inequality, we obtain
\[
	\left(
		1+\alpha-\tfrac{\rho_{k+1}}{\delta_{k+1}}
	\right)
	\D_{\kernel}(x^{k+1},x^k)
\leq
	\tfrac{\delta_{k+1}\rho_{k+1}}{2}
	\Lambda_{k,\delta_{k+1}}
	\DD_{\kernel}(x^k,x^{k-1}),
\]
which plugged into \eqref{eq:Bk:BY} leads to
\begin{equation}
\label{eq:Bk:FNEa}
	B_{k+1}
\leq
	\tfrac{
		(1+\alpha)\delta_{k+1}^2
	}{
		(1+\alpha)\delta_{k+1}-\rho_{k+1}
	}
	\tfrac{\rho_{k+1}}{2}
	\Lambda_{k,\delta_{k+1}}
	\DD_{\kernel}(x^k,x^{k-1}),
\end{equation}
holding for any \(\delta_{k+1}\) such that \((1+\alpha)\delta_{k+1}-\rho_{k+1}>0\).

We may thus complement \eqref{eq:Bk:BY} with a lower bound as
\begin{align*}
