					}{
						\delta_{k+1}^2
						\DD_{\kernel}(x^k,x^{k-1})
					}
				\]
				as in \eqref{eq:Lamk}, where \((\delta_k)_{k\in\N}\subset\R_{++}\) is a bounded sequence.
				If \(\gamma_k\to0\), then \(\Lambda_{k,\delta_{k+1}}\to1\).
			\end{lemma}

\begin{proof}
				For notational conciseness, let us denote \(u^k\coloneqq\nabla\kernel(x^k)-\nabla\kernel(x^{k-1})\) and \(v^k\coloneqq\nabla f(x^k)-\nabla f(x^{k-1})\), so that \(H_k(x^k)-H_k(x^{k-1})=u^k-\gamma_k v^k\).
