				Moreover, letting \(L_{f,\K}^{\kernel}\) denote a smoothness modulus of \(f\) relative to \(\kernel\) on \(\K\), ensured to exist by \cref{ass:f}, we infer from \cite[Prop. 2.5(ii)]{ahookhosh2021bregman} that
				\(
					\norm{v^k}\leq L_{f,\K}^{\kernel} L_{\kernel,\K}\norm{u^k}
				\)
				holds for all \(k\).
				Therefore,
				\begin{align*}
					\abs{\Lambda_{k,\delta_{k+1}}-1}
				\leq{} &
					\norm{\nabla^2\kernel^*(\xi_k)-\nabla^2\kernel^*(\eta_k)}
					L_{\kernel,\K}
					+
					2\gamma_k
					L_{f,\K}^{\kernel} L_{\kernel,\K}^2
					\norm{\nabla^2\kernel^*(\xi_k)}
				\\
				&
					+
					\gamma_k^2
					L_{\kernel,\K}^3
					(L_{f,\K}^{\kernel})^2
					\norm{\nabla^2\kernel^*(\xi_k)}.
				\end{align*}
				If \(\gamma_k\to0\), then eventually \(\gamma_k<\frac{1}{L_{f,\K}^{\kernel}}\) and standard results ensure that \((x^k)_{k\in\N}\) converges to some point \(x\in\K\).
				In this case, \((\xi^k)_{k\in\N}\) and \((\eta^k)_{k\in\N}\) converge to \(\nabla\kernel(x)\) (the former sequence because \((\delta_k)_{k\in\N}\) is bounded), and by continuity of \(\nabla^2\kernel^*\) on \(\K\) the right-hand side in the above inequality vanishes.
			\end{proof}

For notational conciseness, let us denote \(u^k\coloneqq\nabla\kernel(x^k)-\nabla\kernel(x^{k-1})\) and \(v^k\coloneqq\nabla f(x^k)-\nabla f(x^{k-1})\), so that \(H_k(x^k)-H_k(x^{k-1})=u^k-\gamma_k v^k\).
For any \(k\in\N\) there exists
\(\xi^k\) on the line segment between \(\nabla\kernel(x^k)\) and \(\nabla\kernel(x^k)+\delta_{k+1}(H_k(x^k)-H_k(x^{k-1}))\)
and
\(\eta^k\) on the line segment between \(\nabla\kernel(x^k)\) and \(\nabla\kernel(x^{k-1})\)
such that
\begin{align}
\label{eq:Lamknum}
	\Lambda_{k,\delta_{k+1}}
={} &
	\frac{
		2
		\D_{\kernel^*}\bigl(\nabla\kernel(x^k)+\delta_{k+1}\bigl[H_k(x^k)-H_k(x^{k-1})\bigr],\nabla\kernel(x^k)\bigr)
	}{
		\delta_{k+1}^2
		\DD_{\kernel}(x^k,x^{k-1})
	}
\\
\nonumber
={} &
	\frac{
		\innprod{
			\nabla^2\kernel^*(\xi_k)
			\bigl[H_k(x^k)-H_k(x^{k-1})\bigr]
		}{
			H_k(x^k)-H_k(x^{k-1})
		}
	}{
		\innprod{
			\nabla^2\kernel^*(\eta_k)
			u^k
		}{
			u^k
		}
	}
\\
\nonumber
={} &
	\frac{
		\innprod{
			\nabla^2\kernel^*(\xi_k)
			u^k
		}{
			u^k
		}
	}{
		\innprod{
			\nabla^2\kernel^*(\eta_k)
			u^k
		}{
			u^k
		}
	}
	-
	2\gamma_k
	\frac{
		\innprod{
			\nabla^2\kernel^*(\xi_k)
			u^k
		}{
			v^k
		}
	}{
		\innprod{
			\nabla^2\kernel^*(\eta_k)
			u^k
		}{
			u^k
		}
	}
	+
	\gamma_k^2
	\frac{
		\innprod{
			\nabla^2\kernel^*(\xi_k)
			v^k
		}{
			v^k
		}
	}{
		\innprod{
			\nabla^2\kernel^*(\eta_k)
			u^k
		}{
			u^k
		}
	}.
\end{align}

Therefore,
\begin{align*}
	\abs{\Lambda_{k,\delta_{k+1}}-1}
\leq{} &
	\norm{\nabla^2\kernel^*(\xi_k)-\nabla^2\kernel^*(\eta_k)}
	L_{\kernel,\K}
	+
	2\gamma_k
	L_{f,\K}^{\kernel} L_{\kernel,\K}^2
	\norm{\nabla^2\kernel^*(\xi_k)}
\\
&
	+
	\gamma_k^2
	L_{\kernel,\K}^3
	(L_{f,\K}^{\kernel})^2
	\norm{\nabla^2\kernel^*(\xi_k)}.
\end{align*}

\begin{lemma}\label{lem:prox:property:optimal}%
				Additionally to \cref{ass:basic} suppose that \(\argmin_C\varphi\neq\emptyset\).
				Let a sequence \((y^k)_{k\in\N}\) contained in \(C\) and converging to a point \(y^\star\in\argmin_C\varphi\) be fixed, and for every \(k\in\N\) let
				\begin{equation}\label{eq:baryk}
					\bar y^k
				\coloneqq
					\argmin_w\left\{
						g(w)
						+
						\innprod{\nabla f(y^k)}{w-y^k}
						+
						\tfrac{1}{\gamma_{k+1}}\D_{\kernel}(w,y^k)
					\right\}
				\end{equation}
				where \((\gamma_k)_{k\in\N}\) is a bounded sequence of strictly positive stepsizes.
				Then, \(\bar y^k\to y^\star\) and \(\gamma_{k+1}(\varphi(\bar y^k) - \min\varphi)\to0\).
			\end{lemma}

Consider the ``left'' Bregman proximal operator \(\prox_{g}:\interior\dom\kernel\to\dom\kernel\) defined as
\[
	\prox_{g}(y)
\coloneqq
	\argmin_{w\in\R^n}\{g(w)+\D_{\kernel}(w,y)\}
\]
(note that \(\prox_{g}(y)\in\interior\dom\kernel\subseteq\dom\kernel\) for any \(y\in\interior\dom\kernel\), owing to \cref{ass:basic}).
The mapping \(\prox_{\gamma_{k+1}g}\circ\nabla\kernel^*\) is \(\nabla\kernel\)-firmly-nonexpansive, in the sense that
\begin{equation}\label{eq:BPG:FNE}
	\DD_{\kernel}(\bar y_1,\bar y_2)
\leq
	\innprod{\eta_1-\eta_2}{\bar y_1-\bar y_2}
\end{equation}
holds for any \(\eta_i\in\R^2\) and \(\bar y_i = \prox_{\gamma_{k+1} g}\circ\nabla\kernel^*(\eta_i)\), \(i=1,2\);
a proof of this fact can be found in \cite[Lem. 4.2]{wang2022bregman} (see also \cite[Thm. 4.9]{wang2025bregman} for its \emph{equivalence} to convexity of \(g\)).

\begin{theorem}\label{thm:xinC}%
				Additionally to \cref{ass:basic}, suppose that
				\begin{equation}\label{eq:xinC}
					\text{there exists \(x\in C\) such that \(\varphi(x)\leq\inf_{k\in\N}\varphi(x^k)\)}
				\end{equation}
				holds for the iterates \(x^k\) generated by \refBY.
				Then, the sequence \((x^k)_{k\in\N}\) converges to a solution \(x^\star\in\argmin_C\varphi\neq\emptyset\) and \(\varphi(x^k)\to\inf_{\overline C}\varphi\).

				When \(\kernel\) has symmetry coefficient \(\alpha>0\), the same is true for \refFNEa.
			\end{theorem}

Additionally to \cref{ass:basic}, suppose that
\begin{equation}\label{eq:xinC}
	\text{there exists \(x\in C\) such that \(\varphi(x)\leq\inf_{k\in\N}\varphi(x^k)\)}
\end{equation}
holds for the iterates \(x^k\) generated by \refBY.

\begin{proof}
				Having shown that \(\gamma_k\not\to0\), one has that \(\sum_{k\in\N}\gamma_k=\infty\).
				\Cref{thm:Pkmin} then implies that \(\inf_{k\in\N}\varphi(x^k)=\varphi(x)\).
				From the arbitrariness of the point \(x\) as in \eqref{eq:xinC} we conclude that necessarily \(x\in\argmin_C\varphi\subseteq\argmin_{\overline C}\varphi\), with inclusion holding by virtue of \cite[Prop. 11.1(iv)]{bauschke2017convex}.
				Hence \(\inf_{k\in\N}\varphi(x^k)=\inf_{\overline C}\varphi\).
			\end{proof}

In light of the previous claim, the proof of \cref{thm:xinC} is completed once we show that \(x^k\to x^\star\).
To this end, owing to the fact that \(\D_{\kernel}(x^\star,x^k)\leq\U_k(x^\star)\) it will suffice to show that \(U\coloneqq\lim_{k\to\infty}\U_k(x^\star)\) is zero, (existence and finiteness of \(U\) is ensured by \cref{thm:SD}).
\begin{itemize}
\item
	Let us consider a subsequence \((x^k)_{k\in K}\) converging to \(x^\star\).
	If the corresponding subsequence \((\gamma_{k+1})_{k\in K}\) is bounded, then it follows from \cref{lem:prox:property:optimal} that  \(x^{k+1}\to x^\star\) and \(\gamma_{k+1} P_k(x^\star) \to 0\) as well, and from the expression of \(\U_k\) together with the fact that \(\hat\rho_{k+1}\) is bounded and \(\inf_k \alpha_k>0\), it is clear that
	\(\U_{k+1}(x^\star)\to0\) as \(K\ni k\to\infty\).

\item
	In what follows, let us instead consider the complementary case in which for any subsequence \(x^k\) converging to \(x^\star\) the corresponding subsequence of stepsizes \((\gamma_{k+1})_{k\in K}\) is divergent.
	In this case, note that since \(\gamma_{k+1}P_k(x^\star)\leq\U_{k+1}(x^\star)\leq\U_0(x^\star)\), we have
	\begin{align}
	\nonumber
		(x^k)_{k\in K}\to x^\star
	\Leftrightarrow{} &
		(\gamma_{k+1})_{k\in K}\to\infty
	\Leftrightarrow
		\bigl(P_k(x^\star)\bigr)_{k\in K}\to0
	\\
	\nonumber
	\Rightarrow{} &
		(\gamma_k)_{k\in K}\to\infty
	\\
	\Leftrightarrow{} &
		(x^{k-1})_{k\in K}\to x^\star
	\Leftrightarrow
		\bigl(P_{k-1}(x^\star)\bigr)_{k\in K}\to0,
	\label{eq:gamk:infty"gamk-1}
	\end{align}
	where the right implication follows from the fact that \(\gamma_{k+1}\leq\hat\rho_{k+1}\gamma_k\leq\rho_{\rm max}\gamma_k\), for some \(\rho_{\rm max}\leq\frac{1+\sqrt{5}}{2}\).
	Since an optimal limit exists, it follows that \(\sup_{k\in\N}\gamma_k=\infty\).

	In what follows, we construct a specific subsequence \(K\coloneqq\{k_0,k_1,\dots\}\) along which \((\gamma_k)_{k\in K}\) diverges.
	In doing so, we expand upon the arguments in the proof of \cite[Thm. 2.3]{latafat2024adaptive} to account for the complications of the non-Euclidean setting investigated here.
	For \(i\geq0\) let
	\begin{equation}\label{eq:ki+}
		k_{i+1}=\min\{k\geq k_i \mid \gamma_k \geq \rho_{\rm max}\gamma_{k_i}\}.
	\end{equation}
	Then, \(\bigl(\gamma_{k_i}\bigr)_{i\in\N}\to\infty\), which by \eqref{eq:gamk:infty"gamk-1} implies that
	\begin{equation}\label{eq:xkitox*}
		\lim_{i\to\infty}x^{k_i-s}
	=
		x^\star
	\quad
		\forall s=1,2,3
	\end{equation}
	(in fact, for any \(s\in\N\)).
	In light of \cref{thm:SD} we have that
	\begin{equation}\label{eq:U:gamkPk-1}
		U= \lim_{k \to \infty} \U_k= \lim_{i \to \infty} \U_{k_i-1}(x^\star) = \lim_{i \to \infty} \gamma_{k_i-1}(1+ \vartheta_{k_i-1})P_{k_i-2}(x^\star).
	\end{equation}

	We proceed to show that \(\gamma_{k-1} P_{k-2}(x^\star)\) converges to zero along the same subsequence.
	\begin{subequations}
		For every \(i\in\N\), note that
		\begin{gather}
			\rho_{k_i}>1
			~\text{ and }~
			k_{i-1}\leq k_i-1
		\shortintertext{by minimality of \(k_i\) and the fact that \(\rho_{\rm max}>1\), hence that}
		\label{eq:k_i-1}
			\text{either }~
			\rho_{k_i-1}>1
			~\text{ or }~
			\bigl(
				k_i-1\notin K
				\text{ and thus }
				k_{i-1}\leq k_i-2
			\bigr).
		\shortintertext{These combined imply also that}
		\label{eq:k-1}
			\rho_{k_i-1}\geq\rho_{\rm max}^{-1}.
		\end{gather}
		Indeed, if not, then \(\rho_{k_i-1}<\rho_{\rm max}^{-1}<1\), implying by \eqref{eq:k_i-1} that \(k_{i-1}\leq k_i-2\);
		this would lead to the contradiction
		\[
			\rho_{\rm max}\gamma_{k_{i-1}}
		\stackrel{\text{\clap{\eqref{eq:ki+}}}}{\leq}
			\gamma_{k_i}
		\leq
			\rho_{\rm max}\gamma_{k_i-1}
		=
			\rho_{\rm max}\rho_{k_i-1}\gamma_{k_i-2}
		\stackrel{\mathclap{\bot}}{<}
			\gamma_{k_i-2}
		\leq
			\rho_{\rm max}\gamma_{k_{i-1}},
		\]
		where ``\(\bot\)'' marks where the contradictory inequality is used, and the last inequality follows both in case \(k_i-2=k_{i-1}\) (since \(\rho_{\rm max}>1\)) or when \(k_{i-1}<k_i-2<k_i\) (from minimality in the definition of \(k_i\)).
	\end{subequations}
	Therefore, \eqref{eq:k-1} holds true, implying in particular that the sequence
	\begin{equation}\label{eq:Lambda:k-2:bounded}
		\bigl(\Lambda_{k_i-2, 2\hat\rho_{k_i-1}}\bigr)_{i\in\N}
	\quad
		\text{is bounded,}
	\end{equation}
	for otherwise the second term in either \eqref{eq:BY:rhok*} or \eqref{eq:FNEa:rhok*} would vanish, owing to the fact that \(\hat\rho_k\) is lower bounded by \(\sqrt{1/2}\) and similarly \(\alpha_k\) is bounded away from zero.

	Let \(v^k\coloneqq H_k(x^{k-1})- H_k(x^k)\in\gamma_k\partial\varphi(x^k)\), and observe that
	\begin{align*}
	&
		\gamma_k P_{k-1}(x^\star)
	\\
	\leq{} &
		\rho_k\innprod{x^\star - x^{k-1}}{-v^{k-1}}
	\\
	\leq{} &
		\tfrac{\rho_k}{2\hat\rho_k}\D_{\kernel}(x^\star, x^{k-1})
		+
		\tfrac{\rho_k}{2\hat\rho_k}
		\D_{\kernel^*}\bigl(\nabla\kernel(x^{k-1})-2\hat\rho_kv^{k-1}\bigr), \nabla \kernel(x^{k-1})\bigr)
	\\
	={} &
		\tfrac{\rho_k}{2\hat\rho_k}\D_{\kernel}(x^\star, x^{k-1})
		+
		2\rho_k \hat\rho_k^2\Lambda_{k-1, 2\hat\rho_k} \DD_{\kernel}(x^{k-1},x^{k-2})
	\\
	\leq{} &
		\tfrac{1}{2}\D_{\kernel}(x^\star, x^{k-1})
		+
		2\rho_{\rm max}^3 \Lambda_{k-1, 2\hat\rho_k} \DD_{\kernel}(x^{k-1},x^{k-2})
	\end{align*}
	holds for any \(k\), where we used the Bregman--Young inequality \eqref{eq:BY} with parameter \(\delta= \hat\rho_k\) in the second inequality, and \(\rho_k\leq \hat\rho_k\leq \rho_{\rm max}\) in the last one.
	Recall that \(\bigl(x^{k_i-3}\bigr)_{i\in\N} \to x^\star\) by \eqref{eq:xkitox*}.
	Thus,
	\[
		\gamma_{k_i-1} P_{k_i-2}(x^\star)
	\leq
		\tfrac{1}{2}
		\underbrace{
			\D_{\kernel}(x^\star, x^{k_i-2})
			\vphantom{\Lambda_{k_i-2, 2\rho_{k_i-1}}}
		}_{\to 0 \text{ by \eqref{eq:xkitox*}}}
		+
		2\rho_{\rm max}^3
		\underbrace{
			\Lambda_{k_i-2, 2\rho_{k_i-1}}
		}_{\text{\rm bounded}}
		\,
		\underbrace{
			\DD_{\kernel}(x^{k_i-2},x^{k_i-3})
			\vphantom{\Lambda_{k_i-2, 2\rho_{k_i-1}}}
		}_{\to 0 \text{ by \eqref{eq:xkitox*}}}.
	\]
	Using this in \eqref{eq:U:gamkPk-1} and noting that \(\theta_{k_i-1}\) being a multiple of \(\hat{\rho}_{k_i-1}\) in both \refBY{} and \refFNEa{} is bounded, completes the proof.
\end{itemize}

\begin{claim}\label{thm:xinC:boundedseq}
				There exists a compact set \(\K\subset C\) containing all the iterates \(x^k\).
			\end{claim}

\begin{claim}
				\(\gamma_k\not\to0\).
			\end{claim}

Since \((x^k)_{k\in\N}\) is bounded and bounded away from the boundary of \(C\), regardless of whether or not \(\kernel\) has a symmetry coefficient \(\alpha>0\), it holds that \(\inf_{k\in\N}\alpha_k>0\);
furthermore, for both \refBY{} and \refFNEa{} note that \(\hat\rho_{k+1}\leq\sqrt{1+\rho_k}\leq\sqrt{1+\hat\rho_k}\), implying that \(\hat\rho_k\leq\frac{1+\sqrt{5}}{2}\) holds for any \(k\).
As such, in both \eqref{eq:BY:rhok*} and \eqref{eq:FNEa:rhok*} eventually the second element in the minimum is infinite, implying that the update reduces to \(\gamma_{k+1}=\hat\rho_{k+1}\gamma_k\) and is thus divergent, a contradiction.

\begin{claim}
				\(\inf_{k\in\N}\varphi(x^k)=\inf_{\overline C}\varphi\) (in particular, necessarily \(x\in\argmin_C\varphi\) for any \(x\) satisfying \eqref{eq:xinC}).
			\end{claim}

\begin{proof}
				Having shown that \(\gamma_k\not\to0\), one has that \(\sum_{k\in\N}\gamma_k=\infty\).
				\Cref{thm:Pkmin} then implies that \(\inf_{k\in\N}\varphi(x^k)=\varphi(x)\).
				From the arbitrariness of the point \(x\) as in \eqref{eq:xinC} we conclude that necessarily \(x\in\argmin_C\varphi\subseteq\argmin_{\overline C}\varphi\), with inclusion holding by virtue of \cite[Prop. 11.1(iv)]{bauschke2017convex}.
				Hence \(\inf_{k\in\N}\varphi(x^k)=\inf_{\overline C}\varphi\).
			\end{proof}

\begin{claim}\label{claim:unique}%
				There exists exactly one optimal limit point \(x^\star\in\argmin_C\varphi\).
			\end{claim}

In what follows, we construct a specific subsequence \(K\coloneqq\{k_0,k_1,\dots\}\) along which \((\gamma_k)_{k\in K}\) diverges.
In doing so, we expand upon the arguments in the proof of \cite[Thm. 2.3]{latafat2024adaptive} to account for the complications of the non-Euclidean setting investigated here.
For \(i\geq0\) let
\begin{equation}\label{eq:ki+}
	k_{i+1}=\min\{k\geq k_i \mid \gamma_k \geq \rho_{\rm max}\gamma_{k_i}\}.
\end{equation}
Then, \(\bigl(\gamma_{k_i}\bigr)_{i\in\N}\to\infty\), which by \eqref{eq:gamk:infty"gamk-1} implies that
\begin{equation}\label{eq:xkitox*}
	\lim_{i\to\infty}x^{k_i-s}
=
	x^\star
\quad
	\forall s=1,2,3
\end{equation}
(in fact, for any \(s\in\N\)).
In light of \cref{thm:SD} we have that
\begin{equation}\label{eq:U:gamkPk-1}
	U= \lim_{k \to \infty} \U_k= \lim_{i \to \infty} \U_{k_i-1}(x^\star) = \lim_{i \to \infty} \gamma_{k_i-1}(1+ \vartheta_{k_i-1})P_{k_i-2}(x^\star).
\end{equation}

We proceed to show that \(\gamma_{k-1} P_{k-2}(x^\star)\) converges to zero along the same subsequence.
\begin{subequations}
	For every \(i\in\N\), note that
	\begin{gather}
		\rho_{k_i}>1
		~\text{ and }~
		k_{i-1}\leq k_i-1
	\shortintertext{by minimality of \(k_i\) and the fact that \(\rho_{\rm max}>1\), hence that}
	\label{eq:k_i-1}
		\text{either }~
		\rho_{k_i-1}>1
		~\text{ or }~
		\bigl(
			k_i-1\notin K
			\text{ and thus }
			k_{i-1}\leq k_i-2
		\bigr).
	\shortintertext{These combined imply also that}
	\label{eq:k-1}
		\rho_{k_i-1}\geq\rho_{\rm max}^{-1}.
	\end{gather}

	Indeed, if not, then \(\rho_{k_i-1}<\rho_{\rm max}^{-1}<1\), implying by \eqref{eq:k_i-1} that \(k_{i-1}\leq k_i-2\);
	this would lead to the contradiction
	\[
		\rho_{\rm max}\gamma_{k_{i-1}}
	\stackrel{\text{\clap{\eqref{eq:ki+}}}}{\leq}
		\gamma_{k_i}
	\leq
		\rho_{\rm max}\gamma_{k_i-1}
	=
		\rho_{\rm max}\rho_{k_i-1}\gamma_{k_i-2}
	\stackrel{\mathclap{\bot}}{<}
		\gamma_{k_i-2}
	\leq
		\rho_{\rm max}\gamma_{k_{i-1}},
	\]
	where ``\(\bot\)'' marks where the contradictory inequality is used, and the last inequality follows both in case \(k_i-2=k_{i-1}\) (since \(\rho_{\rm max}>1\)) or when \(k_{i-1}<k_i-2<k_i\) (from minimality in the definition of \(k_i\)).
\end{subequations}

Therefore, \eqref{eq:k-1} holds true, implying in particular that the sequence
\begin{equation}\label{eq:Lambda:k-2:bounded}
	\bigl(\Lambda_{k_i-2, 2\hat\rho_{k_i-1}}\bigr)_{i\in\N}
\quad
	\text{is bounded,}
\end{equation}
for otherwise the second term in either \eqref{eq:BY:rhok*} or \eqref{eq:FNEa:rhok*} would vanish, owing to the fact that \(\hat\rho_k\) is lower bounded by \(\sqrt{1/2}\) and similarly \(\alpha_k\) is bounded away from zero.

	Thus,
	\[
		\gamma_{k_i-1} P_{k_i-2}(x^\star)
	\leq
		\tfrac{1}{2}
		\underbrace{
			\D_{\kernel}(x^\star, x^{k_i-2})
			\vphantom{\Lambda_{k_i-2, 2\rho_{k_i-1}}}
		}_{\to 0 \text{ by \eqref{eq:xkitox*}}}
		+
		2\rho_{\rm max}^3
		\underbrace{
			\Lambda_{k_i-2, 2\rho_{k_i-1}}
		}_{\text{\rm bounded}}
		\,
		\underbrace{
			\DD_{\kernel}(x^{k_i-2},x^{k_i-3})
			\vphantom{\Lambda_{k_i-2, 2\rho_{k_i-1}}}
		}_{\to 0 \text{ by \eqref{eq:xkitox*}}}.
	\]
	Using this in \eqref{eq:U:gamkPk-1} and noting that \(\theta_{k_i-1}\) being a multiple of \(\hat{\rho}_{k_i-1}\) in both \refBY{} and \refFNEa{} is bounded, completes the proof.
\end{itemize}
